  { id: 'd12', endpoint: 'https://legacy.example/hooks/payouts', status: 'pending', attempts: 1 }
];

let failNextRequest = false;

/** Mock API, treat it as given: it answers after 400 ms. "Fail next request" makes the next request reject once. */
export function armFailure(): void {
  failNextRequest = true;
}

export function fetchDeliveries(source: Source): Promise<unknown> {
  return new Promise((resolve, reject) => {
    window.setTimeout(() => {
      if (failNextRequest) {
        failNextRequest = false;
        reject(new Error('Gateway timeout'));
        return;
      }
      if (source === 'error') {
        reject(new Error('Gateway timeout'));
        return;
      }
      if (source === 'empty') {
        resolve([]);
        return;
      }
      if (source === 'legacy') {
        resolve(LEGACY_RAW.map((record) => (typeof record === 'object' && record !== null ? { ...record } : record)));
        return;
      }
      resolve(LIVE.map((delivery) => ({ ...delivery })));
    }, 400);
  });
}

/** Mock API: a retry answers after 200 ms and the endpoint accepts the delivery. */
export function retryDelivery(delivery: Delivery): Promise<Delivery> {
  return new Promise((resolve) => {
    window.setTimeout(() => {
      resolve({ ...delivery, status: 'delivered', attempts: delivery.attempts + 1, lastAttempt: new Date().toISOString() });
    }, 200);
  });
}

const STATUSES: readonly DeliveryStatus[] = ['delivered', 'failed', 'pending'];

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null;
}

function isDeliveryStatus(value: unknown): value is DeliveryStatus {
  return typeof value === 'string' && (STATUSES as readonly string[]).includes(value);
}

/** Narrow the raw payload: keep every well-formed record, count the rest. A payload that is not a list is an error. */
export function parseDeliveries(raw: unknown): { deliveries: Delivery[]; skipped: number } {
  if (!Array.isArray(raw)) {
    throw new Error('Unexpected payload');
  }
  const deliveries: Delivery[] = [];
  let skipped = 0;
  for (const record of raw) {
    if (
      isRecord(record) &&
      typeof record.id === 'string' &&
      typeof record.endpoint === 'string' &&
      isDeliveryStatus(record.status) &&
      typeof record.attempts === 'number' &&
      Number.isInteger(record.attempts) &&
      record.attempts >= 0 &&
      typeof record.lastAttempt === 'string'
    ) {
      deliveries.push({
        id: record.id,
        endpoint: record.endpoint,
        status: record.status,
        attempts: record.attempts,
        lastAttempt: record.lastAttempt
      });
    } else {
      skipped += 1;
    }
  }
  return { deliveries, skipped };
}

type RequestState =
  | { kind: 'loading'; keepRows: boolean }
  | { kind: 'ready' }
  | { kind: 'empty' }
  | { kind: 'error'; message: string; keepRows: boolean };

export default function App() {
  const [source, setSource] = useState<Source>('live');
  const [filter, setFilter] = useState<StatusFilter>('all');
  const [deliveries, setDeliveries] = useState<Delivery[]>([]);
  const [skipped, setSkipped] = useState(0);
  const [request, setRequest] = useState<RequestState>({ kind: 'loading', keepRows: false });
  const latestRequest = useRef(0);

  // One request at a time counts: the newest. A refresh keeps the rows on screen; a source change does not.
  function runRequest(nextSource: Source, kind: 'initial' | 'refresh') {
    const requestId = latestRequest.current + 1;
    latestRequest.current = requestId;
    const keepRows = kind === 'refresh' && deliveries.length > 0;
    setRequest({ kind: 'loading', keepRows });
    if (!keepRows) {
      setDeliveries([]);
      setSkipped(0);
    }
    fetchDeliveries(nextSource)
      .then((raw) => {
        if (requestId !== latestRequest.current) return;
        const parsed = parseDeliveries(raw);
        setDeliveries(parsed.deliveries);
        setSkipped(parsed.skipped);
        setRequest(parsed.deliveries.length > 0 ? { kind: 'ready' } : { kind: 'empty' });
      })
      .catch((error: unknown) => {
        if (requestId !== latestRequest.current) return;
        const message = error instanceof Error ? error.message : 'Unknown error';
        setRequest({ kind: 'error', message, keepRows });
      });
  }

  useEffect(() => {
    runRequest(source, 'initial');
    return () => {
      latestRequest.current += 1;
    };
  }, [source]);

  // The refresh handler reads source from the current render, so it never reloads a stale source.
  function handleRefresh() {
    runRequest(source, 'refresh');
  }

  function handleRetryRequest() {
    runRequest(source, request.kind === 'error' && request.keepRows ? 'refresh' : 'initial');
  }

  // Both updates map over the current rows, so a second retry or a refresh in between is never overwritten.
  function handleRetryDelivery(delivery: Delivery) {
    setDeliveries((current) => current.map((item) => (item.id === delivery.id ? { ...item, status: 'pending' } : item)));
    retryDelivery(delivery)
      .then((updated) => {
        setDeliveries((current) =>
          current.map((item) =>
            item.id === updated.id
              ? { ...item, status: updated.status, attempts: updated.attempts, lastAttempt: updated.lastAttempt }
              : item
          )
        );
      })
      .catch(() => {
        setDeliveries((current) => current.map((item) => (item.id === delivery.id ? { ...item, status: 'failed' } : item)));
      });
  }

  const visible = useMemo(
    () => (filter === 'all' ? deliveries : deliveries.filter((delivery) => delivery.status === filter)),
    [deliveries, filter]
  );

  const loading = request.kind === 'loading';
  const countLine = filter === 'all' ? `${deliveries.length} deliveries` : `${visible.length} of ${deliveries.length} deliveries`;

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Webhook Deliveries (Solution)</h1>
          <p className="subtitle">Load the deliveries, type the payload, filter and retry, then fix the refresh.</p>
        </header>

        <div className="toolbar">
          <label className="label" htmlFor="source">Data source</label>
          <select id="source" className="source" value={source} onChange={(event) => setSource(event.target.value as Source)}>
            <option value="live">Live export</option>
            <option value="legacy">Legacy export</option>
            <option value="empty">Empty export</option>
            <option value="error">Failing export</option>
          </select>
          <label className="label" htmlFor="status-filter">Status</label>
          <select
            id="status-filter"
            className="status-filter"
            value={filter}
            onChange={(event) => setFilter(event.target.value as StatusFilter)}
          >
            <option value="all">All</option>
            <option value="delivered">Delivered</option>
            <option value="failed">Failed</option>
            <option value="pending">Pending</option>
          </select>
          <button type="button" className="refresh" onClick={handleRefresh} disabled={loading}>
            Refresh
          </button>
          <button type="button" className="fail-next" onClick={armFailure}>
            Fail next request
          </button>
        </div>

        <div className="status-line" aria-live="polite">
          {request.kind === 'loading' && (
            <span className="status--loading">{request.keepRows ? 'Refreshing deliveries…' : 'Loading deliveries…'}</span>
          )}
          {request.kind === 'error' && (
            <span className="status--error">
              {request.keepRows ? 'Could not refresh the deliveries:' : 'Could not load the deliveries:'} {request.message}{' '}
              <button type="button" className="retry" onClick={handleRetryRequest}>
                Retry
              </button>
            </span>
          )}
          {request.kind === 'empty' && <span className="empty">No deliveries</span>}
          {deliveries.length > 0 && <span className="count">{countLine}</span>}
          {skipped > 0 && <span className="skipped">{skipped} records skipped</span>}
        </div>

        {visible.length > 0 && (
          <div className="table-scroll">
            <table className="deliveries">
              <thead>
                <tr>
                  <th scope="col">Endpoint</th>
                  <th scope="col">Status</th>
                  <th scope="col">Attempts</th>
                  <th scope="col">
                    <span className="visually-hidden">Actions</span>
                  </th>
                </tr>
              </thead>
              <tbody>
                {visible.map((delivery) => (
                  <tr key={delivery.id} className={`row row--${delivery.status}`}>
                    <td className="endpoint">{delivery.endpoint}</td>
                    <td className={`status status--${delivery.status}`}>{delivery.status}</td>
                    <td className="attempts">{delivery.attempts}</td>
                    <td className="actions">
                      {delivery.status === 'failed' && (
                        <button
                          type="button"
                          className="retry-delivery"
                          onClick={() => handleRetryDelivery(delivery)}
                          disabled={loading}
                        >
                          Retry delivery
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </section>
    </main>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import './App.css';

export type Side = 'bid' | 'ask';
export type Scenario = 'steady' | 'late-snapshot' | 'gap' | 'burst';

export interface Level {
  price: number;
  size: number;
}

export interface Snapshot {
  /** The seq of the newest message the snapshot includes. */
  lastSeq: number;
  /** Price levels in no particular order. */
  bids: Level[];
  asks: Level[];
}

/** One price level changed: `size` is the new total at that price, and 0 removes the level. */
export interface Delta {
  seq: number;
  side: Side;
  price: number;
  size: number;
}

export interface FeedConnection {
  /** Answers after 325 ms. The first snapshot of a connection may be older than messages already sent. */
  fetchSnapshot(): Promise<Snapshot>;
  /** Stops the socket and any snapshot still on its way. */
  close(): void;
}

export const DEPTH = 10;
export const UPDATE_BUDGET = 20;

// ---------------------------------------------------------------------------------------------------------------
// Mock exchange: treat everything from here to the commit meter as given.
// ---------------------------------------------------------------------------------------------------------------

function seeded(seed: number): () => number {
  let state = seed >>> 0;
  return () => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seeded(46);
const priceSteps = (from: number, to: number) =>
  Array.from({ length: Math.round((to - from) / 0.5) + 1 }, (_, index) => from + index * 0.5);
const BID_PRICES = priceSteps(90, 99.5);
const ASK_PRICES = priceSteps(100.5, 110);
const randomSize = () => 1 + Math.floor(random() * 40);

/** The book before the first message below (seq 996). */
const BASE = {
  bids: new Map(BID_PRICES.map((price): [number, number] => [price, randomSize()])),
  asks: new Map(ASK_PRICES.map((price): [number, number] => [price, randomSize()])),
};

/** A few messages are fixed so the checks can see them; the rest are random but the same on every run. */
const FIXED: Record<number, Omit<Delta, 'seq'>> = {
  1000: { side: 'bid', price: 95, size: 0 },
  1001: { side: 'ask', price: 100.5, size: 0 },
  1012: { side: 'bid', price: 100, size: 18 },
};

/** Every message the exchange sends, seq 997 to 1720. */
export const MESSAGES: Delta[] = (() => {
  const live = { bids: new Map(BASE.bids), asks: new Map(BASE.asks) };
  const messages: Delta[] = [];
  for (let seq = 997; seq <= 1720; seq += 1) {
    let change = FIXED[seq];
    if (!change) {
      const side: Side = random() < 0.5 ? 'bid' : 'ask';
      const prices = (side === 'bid' ? BID_PRICES : ASK_PRICES).filter((price) => price !== 95 && price !== 100.5);
      const price = prices[Math.floor(random() * prices.length)];
      const levels = side === 'bid' ? live.bids : live.asks;
      const remove = random() < 0.15 && levels.size > 12 && levels.has(price);
      change = { side, price, size: remove ? 0 : randomSize() };
    }
    const levels = change.side === 'bid' ? live.bids : live.asks;
    if (change.size === 0) levels.delete(change.price);
    else levels.set(change.price, change.size);
    messages.push({ seq, ...change });
  }
  return messages;
})();

function bookAt(seq: number): Snapshot {
  const bids = new Map(BASE.bids);
  const asks = new Map(BASE.asks);
  for (const message of MESSAGES) {
    if (message.seq > seq) break;
    const levels = message.side === 'bid' ? bids : asks;
    if (message.size === 0) levels.delete(message.price);
    else levels.set(message.price, message.size);
  }
  const list = (levels: Map<number, number>) => Array.from(levels, ([price, size]) => ({ price, size }));
  return { lastSeq: seq, bids: list(bids), asks: list(asks) };
}

const SNAPSHOT_DELAY = 325;

/** When each scenario sends what. `drop` is a message the exchange sends but the socket loses. */
const PLANS: Record<
  Scenario,
  { firstSeq: number; lastSeq: number; firstAt: number; every: number; perTick: number; firstSnapshot: number; drop?: number }
> = {
  steady: { firstSeq: 1001, lastSeq: 1030, firstAt: 600, every: 50, perTick: 1, firstSnapshot: 1000 },
  'late-snapshot': { firstSeq: 997, lastSeq: 1030, firstAt: 50, every: 50, perTick: 1, firstSnapshot: 999 },
  gap: { firstSeq: 1001, lastSeq: 1030, firstAt: 600, every: 50, perTick: 1, firstSnapshot: 1000, drop: 1012 },
  burst: { firstSeq: 1001, lastSeq: 1720, firstAt: 600, every: 5, perTick: 3, firstSnapshot: 1000 },
};

/**
 * Opens the socket for a scenario. Messages arrive through `onMessage` in seq order, except that one can be lost.
 * The first snapshot describes the book at a fixed seq (1000, or 999 when the snapshot is late); a later one
 * describes it at the newest seq the exchange has sent, lost messages included.
 */
export function connectFeed(scenario: Scenario, onMessage: (delta: Delta) => void): FeedConnection {
  const plan = PLANS[scenario];
  let sentSeq = plan.firstSeq - 1;
  let snapshots = 0;
  let interval = 0;
  const timeouts = new Set<number>();

  const tick = () => {
    for (let sent = 0; sent < plan.perTick && sentSeq < plan.lastSeq; sent += 1) {
      sentSeq += 1;
      if (sentSeq !== plan.drop) onMessage({ ...MESSAGES[sentSeq - 997] });
    }
    if (sentSeq >= plan.lastSeq) window.clearInterval(interval);
  };
  const start = window.setTimeout(() => {
    timeouts.delete(start);
    tick();
    if (sentSeq < plan.lastSeq) interval = window.setInterval(tick, plan.every);
  }, plan.firstAt);
  timeouts.add(start);

  return {
    fetchSnapshot() {
      const seq = snapshots === 0 ? plan.firstSnapshot : sentSeq;
      snapshots += 1;
      return new Promise((resolve) => {
        const id = window.setTimeout(() => {
          timeouts.delete(id);
          resolve(bookAt(seq));
        }, SNAPSHOT_DELAY);
        timeouts.add(id);
      });
    },
    close() {
      timeouts.forEach((id) => window.clearTimeout(id));
      timeouts.clear();
      window.clearInterval(interval);
    },
  };
}

/**
 * Given: an update meter for the burst check. It counts the DOM updates inside the book (one per commit or direct
 * write that changes it) in a sliding one-second window and shows the peak since the scenario changed.
 * Keep `ref={bookRef}` on `.book`, render the rows inside it, and keep `ref={meterRef}` on `.update-meter`.
 */
function useUpdateMeter(resetKey: string) {
  const bookRef = useRef<HTMLDivElement>(null);
  const meterRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const book = bookRef.current;
    const meter = meterRef.current;
    if (!book || !meter) return;
    let stamps: number[] = [];
    let peak = 0;
    const observer = new MutationObserver(() => {
      const now = performance.now();
      stamps = stamps.filter((stamp) => now - stamp < 1000);
      stamps.push(now);
      peak = Math.max(peak, stamps.length);
      meter.textContent = `${peak > UPDATE_BUDGET ? 'Over budget' : 'Within budget'}: peak ${peak} book updates per second`;
    });
    observer.observe(book, { childList: true, subtree: true, characterData: true });
    return () => observer.disconnect();
  }, [resetKey]);
  return { bookRef, meterRef };
}

// ---------------------------------------------------------------------------------------------------------------

type Status = 'loading' | 'live' | 'resyncing';

interface Book {
  bids: Map<number, number>;
  asks: Map<number, number>;
}

interface View {
  bids: Level[];
  asks: Level[];
  lastSeq: number | null;
}

const STATUS_TEXT: Record<Status, string> = { loading: 'Loading snapshot…', live: 'Live', resyncing: 'Resyncing…' };
const EMPTY_VIEW: View = { bids: [], asks: [], lastSeq: null };
const DRAW_EVERY = 100;

function bestLevels(levels: Map<number, number>, side: Side): Level[] {
  return Array.from(levels, ([price, size]) => ({ price, size }))
    .sort((a, b) => (side === 'bid' ? b.price - a.price : a.price - b.price))
    .slice(0, DEPTH);
}

function toLevels(levels: Level[]): Map<number, number> {
  return new Map(levels.map((level): [number, number] => [level.price, level.size]));
}

export default function App() {
  const [scenario, setScenario] = useState<Scenario>('steady');
  const [view, setView] = useState<View>(EMPTY_VIEW);
  const [status, setStatus] = useState<Status>('loading');
  const [resyncs, setResyncs] = useState(0);
  const { bookRef, meterRef } = useUpdateMeter(scenario);

  useEffect(() => {
    // The book lives outside React state: messages change it at socket speed, and the screen follows on a timer.
    const book: Book = { bids: new Map(), asks: new Map() };
    let lastSeq: number | null = null;
    const pending: Delta[] = [];
    let syncing = true;
    let changed = false;
    let closed = false;
    let retry = 0;

    const apply = (delta: Delta) => {
      const levels = delta.side === 'bid' ? book.bids : book.asks;
      if (delta.size === 0) levels.delete(delta.price);
      else levels.set(delta.price, delta.size);
      lastSeq = delta.seq;
      changed = true;
    };

    // Applies pending messages in arrival order: one the snapshot already includes is skipped, and a jump past
    // the next seq is a gap that starts a resync and stays queued.
    const drain = () => {
      let index = 0;
      while (!syncing && lastSeq !== null && index < pending.length) {
        const next = pending[index];
        if (next.seq > lastSeq + 1) {
          resync();
          break;
        }
        if (next.seq === lastSeq + 1) apply(next);
        index += 1;
      }
      pending.splice(0, index);
    };

    const draw = () => {
      if (!changed || closed) return;
      changed = false;
      setView({ bids: bestLevels(book.bids, 'bid'), asks: bestLevels(book.asks, 'ask'), lastSeq });
    };

    // The first load and every resync ask the same connection for a snapshot. Only a failed request retries;
    // an error thrown while applying the snapshot is not swallowed.
    const load = () => {
      connection.fetchSnapshot().then(
        (snapshot) => {
          if (closed) return;
          book.bids = toLevels(snapshot.bids);
          book.asks = toLevels(snapshot.asks);
          lastSeq = snapshot.lastSeq;
          changed = true;
          syncing = false;
          drain();
          if (!syncing) {
            setStatus('live');
            draw();
          }
        },
        () => {
          if (!closed) retry = window.setTimeout(load, 1000);
        }
      );
    };

    // The last book stays on screen while a new snapshot loads; messages keep queueing behind it.
    const resync = () => {
      syncing = true;
      setStatus('resyncing');
      setResyncs((count) => count + 1);
      load();
    };

    const connection = connectFeed(scenario, (delta) => {
      if (closed) return;
      pending.push(delta);
      drain();
    });
    load();
    const timer = window.setInterval(draw, DRAW_EVERY);

    return () => {
      closed = true;
      connection.close();
      window.clearInterval(timer);
      window.clearTimeout(retry);
    };
  }, [scenario]);

  // Clearing here rather than in the effect keeps the old book out of the first commit of the new scenario.
  const changeScenario = (next: Scenario) => {
    setScenario(next);
    setView(EMPTY_VIEW);
    setStatus('loading');
    setResyncs(0);
  };

  const bestBid = view.bids[0];
  const bestAsk = view.asks[0];
  const spread = bestBid && bestAsk ? `Spread ${(bestAsk.price - bestBid.price).toFixed(2)}` : 'Spread —';

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Order Book (Solution)</h1>
          <p className="subtitle">A snapshot, then deltas over a socket. Keep the book right and the screen calm.</p>
        </header>

        <div className="toolbar">
          <label className="label" htmlFor="scenario">Feed scenario</label>
          <select
            id="scenario"
            className="scenario"
            value={scenario}
            onChange={(event) => changeScenario(event.target.value as Scenario)}
          >
            <option value="steady">Steady feed</option>
            <option value="late-snapshot">Snapshot after the first messages</option>
            <option value="gap">Lost message</option>
            <option value="burst">Burst</option>
          </select>
        </div>

        <div className="status-line">
          <span className="status-live" aria-live="polite">
            <span className="sync-status">{STATUS_TEXT[status]}</span>
            <span className="resync-count">
              {resyncs} {resyncs === 1 ? 'resync' : 'resyncs'}
            </span>
          </span>
          <span className="last-seq">Last update {view.lastSeq === null ? '—' : `#${view.lastSeq}`}</span>
        </div>
        <span className="update-meter" ref={meterRef} />

        <p className="spread">{spread}</p>
        <div className={`book${status === 'resyncing' ? ' book--stale' : ''}`} ref={bookRef}>
          <section className="side" aria-label="Bids">
            <h2 className="side-title">Bids</h2>
            <ol className="bids">
              {view.bids.map((level) => (
                <li key={level.price} className="level bid">
                  <span className="price">{level.price.toFixed(2)}</span>
                  <span className="size">{level.size}</span>
                </li>
              ))}
            </ol>
          </section>
          <section className="side" aria-label="Asks">
            <h2 className="side-title">Asks</h2>
            <ol className="asks">
              {view.asks.map((level) => (
                <li key={level.price} className="level ask">
                  <span className="price">{level.price.toFixed(2)}</span>
                  <span className="size">{level.size}</span>
                </li>
              ))}
            </ol>
          </section>
        </div>
      </section>
    </main>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import './App.css';

export interface Payment {
  id: number;
  amountCents: number;
}

export const ITEM_COUNT = 10000;
export const ROW_HEIGHT = 36;
export const VIEWPORT_HEIGHT = 360;
export const VISIBLE_ROWS = VIEWPORT_HEIGHT / ROW_HEIGHT;
export const OVERSCAN = 5;
export const POOL_SIZE = VISIBLE_ROWS + 2 * OVERSCAN;

/** Ten thousand payments, the same on every run. */
export const PAYMENTS: Payment[] = Array.from({ length: ITEM_COUNT }, (_, index) => ({
  id: index + 1,
  amountCents: ((index + 1) * 2654435761) % 100000,
}));

const numberFormat = new Intl.NumberFormat('en-US');
const moneyFormat = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' });
export const formatNumber = (value: number) => numberFormat.format(value);
export const formatMoney = (cents: number) => moneyFormat.format(cents / 100);

/**
 * Given: counts the row nodes ever created inside the list, so the recycling check can read it. Keep
 * `ref={listRef}` on `.viewport` and `ref={meterRef}` on `.row-meter`.
 */
function useRowNodeMeter() {
  const listRef = useRef<HTMLDivElement>(null);
  const meterRef = useRef<HTMLSpanElement>(null);
  useEffect(() => {
    const list = listRef.current;
    const meter = meterRef.current;
    if (!list || !meter) return;
    const seen = new WeakSet<Element>();
    let created = 0;
    const note = (node: Node) => {
      if (!(node instanceof Element)) return;
      const rows = node.matches('.row') ? [node] : Array.from(node.querySelectorAll('.row'));
      for (const row of rows) {
        if (seen.has(row)) continue;
        seen.add(row);
        created += 1;
      }
    };
    const show = () => {
      meter.textContent = `${formatNumber(created)} row nodes created`;
    };
    note(list);
    show();
    const observer = new MutationObserver((records) => {
      for (const record of records) record.addedNodes.forEach(note);
      show();
    });
    observer.observe(list, { childList: true, subtree: true });
    return () => observer.disconnect();
  }, []);
  return { listRef, meterRef };
}

const LAST_FIRST_ROW = ITEM_COUNT - VISIBLE_ROWS;

/**
 * The row at the top edge of the viewport, partly scrolled out or not. A row with less than half a pixel left on
 * screen counts as scrolled out: a zoomed browser can report 173519.4px for a jump to 173520px.
 */
function rowAt(scrollTop: number) {
  return Math.min(Math.max(Math.floor((scrollTop + 0.5) / ROW_HEIGHT), 0), LAST_FIRST_ROW);
}

export default function App() {
  const { listRef, meterRef } = useRowNodeMeter();
  // Only the first visible row is state: a scroll that stays inside one row sets the same number, and React bails
  // out without committing anything.
  const [firstVisible, setFirstVisible] = useState(0);
  const [jumpText, setJumpText] = useState('');
  const [jumpStatus, setJumpStatus] = useState('');

  const start = Math.min(Math.max(firstVisible - OVERSCAN, 0), ITEM_COUNT - POOL_SIZE);
  const indexes = Array.from({ length: POOL_SIZE }, (_, offset) => start + offset);

  // A jump moves the list and sets the window in the same handler, from the position the browser applied.
  const handleJump = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    const list = listRef.current;
    const target = Number(jumpText.trim());
    if (!/^\d+$/.test(jumpText.trim()) || target < 1 || !list) {
      setJumpStatus(`Enter a whole payment number from 1 to ${formatNumber(ITEM_COUNT)}.`);
      return;
    }
    list.scrollTop = Math.min(target - 1, LAST_FIRST_ROW) * ROW_HEIGHT;
    const row = rowAt(list.scrollTop);
    setFirstVisible(row);
    setJumpStatus(`Jumped to payment ${formatNumber(row + 1)}.`);
  };

  return (
    <main className="main">
      <section className="card">
        <header className="header">
          <h1 className="title">Payments (Solution)</h1>
          <p className="subtitle">Ten thousand rows. Draw the twenty that matter.</p>
        </header>

        <form className="jump-form" onSubmit={handleJump}>
          <label className="label" htmlFor="jump">Jump to payment</label>
          <input
            id="jump"
            className="jump"
            type="text"
            inputMode="numeric"
            autoComplete="off"
            value={jumpText}
            onChange={(event) => setJumpText(event.target.value)}
          />
          <button type="submit" className="go">Go</button>
          <p className="jump-status" role="status">{jumpStatus}</p>
        </form>

        <div className="list-status">
          <p className="range">
            Showing {formatNumber(firstVisible + 1)}–{formatNumber(firstVisible + VISIBLE_ROWS)} of {formatNumber(ITEM_COUNT)}
          </p>
          <span className="row-meter" ref={meterRef} />
        </div>

        <div
          className="viewport"
          ref={listRef}
          role="list"
          aria-label="Payments"
          tabIndex={0}
          style={{ height: VIEWPORT_HEIGHT }}
          onScroll={(event) => setFirstVisible(rowAt(event.currentTarget.scrollTop))}
        >
          <div className="spacer" style={{ height: ITEM_COUNT * ROW_HEIGHT }}>
            {indexes.map((index, offset) => {
              const payment = PAYMENTS[index];
              // Keyed by position in the pool: element 0 always shows the pool's first payment, so scrolling
              // rewrites the twenty elements in place and never creates, removes or reorders one.
              return (
                <div
                  key={offset}
                  className="row"
                  role="listitem"
                  aria-posinset={payment.id}
                  aria-setsize={ITEM_COUNT}
                  data-id={payment.id}
                  style={{ transform: `translateY(${index * ROW_HEIGHT}px)` }}
                >
                  <span className="payment">Payment {formatNumber(payment.id)}</span>
                  <span className="amount">{formatMoney(payment.amountCents)}</span>
                </div>
              );
            })}
          </div>
        </div>
      </section>
    </main>
  );
}

import React, { useEffect, useId, useLayoutEffect, useRef, useState } from 'react';
import { createPortal } from 'react-dom';
import './App.css';

export const PROJECT_NAME = 'atlas-web';

/** Space between a tooltip and its button, and the least space between a tooltip and the page's sides, in px. */
export const TOOLTIP_GAP = 8;

export interface Help {
  /** The info button's accessible name. */
  name: string;
  /** What the tooltip says. */
  text: string;
}

export interface Field {
  label: string;
  value: string;
  help?: Help;
}

export const FIELDS: Field[] = [
  { label: 'Project name', value: PROJECT_NAME },
  {
    label: 'Region',
    value: 'Frankfurt',
    help: {
      name: 'About regions',
      text: 'Builds run and logs are stored in this region. Moving a project to another region pauses its deploys for up to an hour.',
    },
  },
  { label: 'Build cache', value: 'On' },
  {
    label: 'Log retention',
    value: '30 days',
    help: {
      name: 'About log retention',
      text: 'Logs older than this are deleted every night. Logs you exported are kept until you delete them yourself.',
    },
  },
  { label: 'Deploy alerts', value: 'Email' },
  { label: 'Preview deploys', value: 'Every branch' },
];

/** The kinds of control Tab can reach in this dialog; a disabled one is left out because Tab skips it. */
const FOCUSABLE = [
  'a[href]',
  'button:not(:disabled)',
  'input:not(:disabled)',
  'select:not(:disabled)',
  'textarea:not(:disabled)',
  '[tabindex]:not([tabindex="-1"]):not(:disabled)',
].join(', ');

interface TooltipPosition {
  top: number;
  left: number;
  placement: 'top' | 'bottom';
}

function InfoButton({ help, boundaryRef }: { help: Help; boundaryRef: { current: HTMLDivElement | null } }) {
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const [position, setPosition] = useState<TooltipPosition | null>(null);
  const [layoutVersion, setLayoutVersion] = useState(0);
  const buttonRef = useRef<HTMLButtonElement>(null);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const tooltipId = useId();
  // Hover and focus each keep the tooltip open, so a pointer leaving a focused button does not close it. Escape
  // dismisses it until the next hover or focus.
  const shown = (hovered || focused) && !dismissed;

  // The first render puts the tooltip in the page hidden, so it has a size; this measures it and places it before
  // the browser paints, below the button when it fits inside the panel and above it when it does not.
  useLayoutEffect(() => {
    const button = buttonRef.current;
    const tooltip = tooltipRef.current;
    const boundary = boundaryRef.current;
    if (!shown || !button || !tooltip || !boundary) {
      setPosition(null);
      return;
    }
    const anchor = button.getBoundingClientRect();
    const size = tooltip.getBoundingClientRect();
    const fitsBelow = anchor.bottom + TOOLTIP_GAP + size.height <= boundary.getBoundingClientRect().bottom;
    const centered = anchor.left + anchor.width / 2 - size.width / 2;
    const rightmost = document.documentElement.clientWidth - TOOLTIP_GAP - size.width;
    // Rects are relative to the window; the tooltip is placed in the page, so it scrolls with the page.
    setPosition({
      top: (fitsBelow ? anchor.bottom + TOOLTIP_GAP : anchor.top - TOOLTIP_GAP - size.height) + window.scrollY,
      left: Math.max(TOOLTIP_GAP, Math.min(centered, rightmost)) + window.scrollX,
      placement: fitsBelow ? 'bottom' : 'top',
    });
  }, [shown, boundaryRef, layoutVersion]);

  // While the tooltip shows, Escape dismisses it wherever focus is. A scroll of the panel places it again while its
  // button is inside the panel, give or take a pixel, as after the scroll a browser makes to reveal a button it has
  // just focused, and hides it once the button is partly scrolled out. A resize places it again.
  useEffect(() => {
    const boundary = boundaryRef.current;
    if (!shown || !boundary) return;
    const place = () => setLayoutVersion((version) => version + 1);
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setDismissed(true);
    };
    const onScroll = () => {
      const button = buttonRef.current?.getBoundingClientRect();
      const panel = boundary.getBoundingClientRect();
      // A pixel of slack: the scroll that reveals a focused button can stop half a pixel short of the edge.
      if (!button || button.top < panel.top - 1 || button.bottom > panel.bottom + 1) setDismissed(true);
      else place();
    };
    const onResize = place;
    document.addEventListener('keydown', onKeyDown);
    boundary.addEventListener('scroll', onScroll);
    window.addEventListener('resize', onResize);
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      boundary.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onResize);
    };
  }, [shown, boundaryRef]);

  return (
    <span className="info-anchor">
      <button
        ref={buttonRef}
        type="button"
        className="info"
        aria-label={help.name}
        aria-describedby={shown ? tooltipId : undefined}
        onMouseEnter={() => {
          setHovered(true);
          setDismissed(false);
        }}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => {
          setFocused(true);
          setDismissed(false);
        }}
        onBlur={() => setFocused(false)}
      >
        i
      </button>
      {shown &&
        createPortal(
          <div
            ref={tooltipRef}
            id={tooltipId}
            role="tooltip"
            className="tooltip"
            data-placement={position?.placement}
            style={position ? { top: position.top, left: position.left } : { top: 0, left: 0, visibility: 'hidden' }}
          >
            {help.text}
          </div>,
          document.body,
        )}
    </span>
  );
}

export default function App() {
  const [open, setOpen] = useState(false);
  const [confirmText, setConfirmText] = useState('');
  const [status, setStatus] = useState('');
  const pageRef = useRef<HTMLElement>(null);
  const settingsRef = useRef<HTMLDivElement>(null);
  const deleteRef = useRef<HTMLButtonElement>(null);
  const dialogRef = useRef<HTMLDivElement>(null);
  const confirmRef = useRef<HTMLInputElement>(null);
  const pressOnBackdrop = useRef({ down: false, up: false });
  const wasOpen = useRef(false);
  const titleId = useId();

  const closeDialog = () => {
    setOpen(false);
    setConfirmText('');
  };

  // While the dialog is open, the page behind it is inert and does not scroll, and Escape closes it wherever focus
  // is: focus can still end up outside the dialog, on the body after a focused control is disabled or after the
  // user comes back from the browser's toolbar. A layout effect's cleanup runs in the commit that removes the
  // dialog, on close and on unmount alike, so the page is never left inert without it. Focus goes back to the
  // trigger only on a close, after the cleanup has freed the page, because an inert button cannot take focus.
  useLayoutEffect(() => {
    if (!open) {
      if (wasOpen.current) deleteRef.current?.focus();
      wasOpen.current = false;
      return;
    }
    wasOpen.current = true;
    const page = pageRef.current;
    // Escape also cancels an input method's composition; that one is not meant for the dialog.
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key !== 'Escape' || event.isComposing) return;
      event.preventDefault();
      closeDialog();
    };
    page?.setAttribute('inert', '');
    document.body.classList.add('modal-open');
    document.addEventListener('keydown', onKeyDown);
    confirmRef.current?.focus();
    return () => {
      document.removeEventListener('keydown', onKeyDown);
      page?.removeAttribute('inert');
      document.body.classList.remove('modal-open');
    };
  }, [open]);

  const deleteProject = () => {
    closeDialog();
    setStatus(`${PROJECT_NAME} is scheduled for deletion.`);
  };

  const handleDialogKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key !== 'Tab' || !dialogRef.current) return;
    // Read the controls on every Tab: the delete button joins them only once the name matches.
    const controls = Array.from(dialogRef.current.querySelectorAll<HTMLElement>(FOCUSABLE));
    if (controls.length === 0) return;
    const first = controls[0];
    const last = controls[controls.length - 1];
    const active = document.activeElement;
    // A click on the dialog's text focuses the dialog itself; Shift+Tab from there goes to the last control too.
    if (event.shiftKey && (active === first || active === dialogRef.current)) {
      event.preventDefault();
      last.focus();
    } else if (!event.shiftKey && active === last) {
      event.preventDefault();
      first.focus();
    }
  };

  return (
    <main className="page" ref={pageRef}>
      <header className="topbar">
        <a className="back" href="#deployments">
          Deployments
        </a>
        <span className="crumb">/ {PROJECT_NAME} / Settings</span>
      </header>
      <section className="card">
        <header className="card-header">
          <h1 className="title">Project settings</h1>
          <p className="subtitle">{PROJECT_NAME} · Production</p>
        </header>

        <div className="settings" ref={settingsRef}>
          {FIELDS.map((field) => (
            <div className="field" key={field.label}>
              <span className="field-label">
                {field.label}
                {field.help && <InfoButton help={field.help} boundaryRef={settingsRef} />}
              </span>
              <span className="field-value">{field.value}</span>
            </div>
          ))}
        </div>

        <footer className="danger">
          <div className="danger-copy">
            <h2 className="danger-title">Delete project</h2>
            <p className="danger-text">Removes every deployment, environment and log.</p>
          </div>
          <button ref={deleteRef} type="button" className="delete" onClick={() => setOpen(true)}>
            Delete project
          </button>
        </footer>
        <p className="status" role="status">{status}</p>
      </section>

      {open &&
        createPortal(
          <div
            className="modal-backdrop"
            // A drag between the dialog and the backdrop, such as selecting the typed name, ends in a click on the
            // backdrop, the element that holds both. Only a press and a release that both land on the backdrop close
            // the dialog; a click inside it bubbles here too and is ignored.
            onMouseDown={(event) => {
              const onBackdrop = event.target === event.currentTarget;
              // A press on the backdrop would move focus to the body, out of reach of the dialog's Tab handling.
              if (onBackdrop) event.preventDefault();
              pressOnBackdrop.current = { down: onBackdrop, up: false };
            }}
            onMouseUp={(event) => {
              pressOnBackdrop.current.up = event.target === event.currentTarget;
            }}
            onClick={(event) => {
              const { down, up } = pressOnBackdrop.current;
              pressOnBackdrop.current = { down: false, up: false };
              if (event.target === event.currentTarget && down && up) closeDialog();
            }}
          >
            <div
              ref={dialogRef}
              className="modal"
              role="dialog"
              aria-modal="true"
              aria-labelledby={titleId}
              tabIndex={-1}
              onKeyDown={handleDialogKeyDown}
            >
              <h2 id={titleId} className="modal-title">Delete {PROJECT_NAME}?</h2>
              <p className="modal-text">This removes 14 deployments, 3 environments and every log within the hour.</p>
              <label className="confirm-label" htmlFor="confirm-name">
                Type <strong>{PROJECT_NAME}</strong> to confirm
              </label>
              <input
                ref={confirmRef}
                id="confirm-name"
                className="confirm-input"
                autoComplete="off"
                spellCheck={false}
                value={confirmText}
                onChange={(event) => setConfirmText(event.target.value)}
              />
              <div className="modal-actions">
                <button type="button" className="cancel" onClick={closeDialog}>
                  Cancel
                </button>
                <button
                  type="button"
                  className="confirm-delete"
                  disabled={confirmText !== PROJECT_NAME}
                  onClick={deleteProject}
                >
                  Delete this project
                </button>
              </div>
            </div>
          </div>,
          document.body,
        )}
    </main>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import './App.css';

/** The largest receipt the upload accepts, in bytes (2 MB). */
export const MAX_BYTES = 2 * 1024 * 1024;
export const ACCEPTED_TYPES = ['image/png', 'image/jpeg'];
/** Time between two progress reports of the fake upload, in ms. */
export const PROGRESS_STEP_MS = 150;

export interface UploadOptions {
  onProgress: (percent: number) => void;
  signal: AbortSignal;
}

const failedOnce = new Set<string>();
let uploadsStarted = 0;

/**
 * Given: a fake receipt upload. It reports progress four times, 25% at a time, PROGRESS_STEP_MS apart, then resolves
 * with the receipt's id. An upload of a name containing "flaky" fails instead of reporting 75%, the first time an
 * upload of that name gets that far in this page; later ones succeed. Aborting the signal stops the reports and
 * rejects with an AbortError.
 */
export function uploadReceipt(file: File, { onProgress, signal }: UploadOptions): Promise<{ id: string }> {
  return new Promise((resolve, reject) => {
    uploadsStarted += 1;
    const id = `receipt-${uploadsStarted}`;
    let percent = 0;
    let timer = 0;
    const abort = () => {
      window.clearTimeout(timer);
      reject(new DOMException('The upload was cancelled.', 'AbortError'));
    };
    if (signal.aborted) {
      abort();
      return;
    }
    signal.addEventListener('abort', abort, { once: true });
    const tick = () => {
      percent += 25;
      if (percent === 75 && file.name.includes('flaky') && !failedOnce.has(file.name)) {
        failedOnce.add(file.name);
        signal.removeEventListener('abort', abort);
        reject(new Error('The server rejected the upload.'));
        return;
      }
      onProgress(percent);
      if (percent < 100) {
        timer = window.setTimeout(tick, PROGRESS_STEP_MS);
        return;
      }
      signal.removeEventListener('abort', abort);
      resolve({ id });
    };
    timer = window.setTimeout(tick, PROGRESS_STEP_MS);
  });
}

/**
 * Given: counts preview URLs, so the checks can read them. It wraps URL.createObjectURL and URL.revokeObjectURL and
 * writes the number of open URLs to document.body's data-preview-urls attribute, and the number ever created to
 * data-preview-urls-created. Both stay after App unmounts.
 */
const openPreviewUrls = new Set<string>();
let createdPreviewUrls = 0;
const createUrl = URL.createObjectURL.bind(URL);
const revokeUrl = URL.revokeObjectURL.bind(URL);
const showOpenPreviewUrls = () => {
  document.body.dataset.previewUrls = String(openPreviewUrls.size);
  document.body.dataset.previewUrlsCreated = String(createdPreviewUrls);
};
URL.createObjectURL = (object: Blob | MediaSource) => {
  const url = createUrl(object);
  createdPreviewUrls += 1;
  openPreviewUrls.add(url);
  showOpenPreviewUrls();
  return url;
};
URL.revokeObjectURL = (url: string) => {
  openPreviewUrls.delete(url);
  revokeUrl(url);
  showOpenPreviewUrls();
};
showOpenPreviewUrls();

type UploadStatus = 'uploading' | 'uploaded' | 'failed' | 'cancelled';

interface Upload {
  /** One per row, so two files with the same name stay two rows. */
  key: number;
  file: File;
  previewUrl: string;
  status: UploadStatus;
  percent: number;
}

const STATUS_TEXT: Record<Exclude<UploadStatus, 'uploading'>, string> = {
  uploaded: 'Uploaded',
  failed: 'Upload failed',
  cancelled: 'Cancelled',
};

/** Why a file cannot be uploaded, or null when it can. The type comes first: a large PDF is the wrong type. */
function rejectionOf(file: File): string | null {
  if (!ACCEPTED_TYPES.includes(file.type)) return `${file.name} is not a PNG or JPEG image.`;
  if (file.size > MAX_BYTES) return `${file.name} is larger than ${MAX_BYTES / 1024 / 1024} MB.`;
  return null;
}

/** Whether a drag carries files, rather than text or a link dragged from the page. */
const carriesFiles = (transfer: DataTransfer | null) => !!transfer && Array.from(transfer.types).includes('Files');

/** Where focus goes after the render a click causes, so a keyboard user stays in the list. */
type PendingFocus = { key: number; control: 'retry' | 'cancel-upload' | 'remove' } | 'choose' | null;

export default function App() {
  const [uploads, setUploads] = useState<Upload[]>([]);
  const [rejections, setRejections] = useState<{ id: number; text: string }[]>([]);
  const [dragActive, setDragActive] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);
  const chooseRef = useRef<HTMLButtonElement>(null);
  const zoneRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLUListElement>(null);
  const pendingFocus = useRef<PendingFocus>(null);
  const nextKey = useRef(1);
  const nextRejection = useRef(1);
  const dragDepth = useRef(0);
  // Kept outside state, so a handler and the unmount cleanup always see the current ones.
  const controllers = useRef(new Map<number, AbortController>());
  const previewUrls = useRef(new Map<number, string>());

  // When App unmounts, stop every running upload and release every preview URL.
  useEffect(() => {
    const running = controllers.current;
    const urls = previewUrls.current;
    return () => {
      running.forEach((controller) => controller.abort());
      urls.forEach((url) => URL.revokeObjectURL(url));
    };
  }, []);

  // A file dropped next to the zone would replace the page, so file drags are cancelled everywhere; only the zone
  // adds the files.
  useEffect(() => {
    const guard = (event: DragEvent) => {
      if (!carriesFiles(event.dataTransfer)) return;
      event.preventDefault();
      // Outside the zone, the cursor shows that a drop would do nothing.
      if (event.type === 'dragover' && event.dataTransfer && !zoneRef.current?.contains(event.target as Node)) {
        event.dataTransfer.dropEffect = 'none';
      }
      if (event.type === 'drop') {
        dragDepth.current = 0;
        setDragActive(false);
      }
    };
    window.addEventListener('dragover', guard);
    window.addEventListener('drop', guard);
    return () => {
      window.removeEventListener('dragover', guard);
      window.removeEventListener('drop', guard);
    };
  }, []);

  // Cancel, Retry and Remove each take away the button that was clicked; move focus to its counterpart.
  useEffect(() => {
    const target = pendingFocus.current;
    if (!target) return;
    pendingFocus.current = null;
    if (target === 'choose') {
      chooseRef.current?.focus();
      return;
    }
    // A row that finished just before Cancel has no Retry; its Remove is the closest control left.
    const row = listRef.current?.querySelector<HTMLElement>(`[data-key="${target.key}"]`);
    (row?.querySelector<HTMLElement>(`.${target.control}`) ?? row?.querySelector<HTMLElement>('.remove'))?.focus();
  });

  const update = (key: number, change: Partial<Upload>) => {
    setUploads((current) => current.map((upload) => (upload.key === key ? { ...upload, ...change } : upload)));
  };

  // An upload that ends on its own takes its Cancel button away; if that button had focus, hand it on.
  const keepFocusAfterEnd = (key: number, control: 'retry' | 'remove') => {
    const cancelButton = listRef.current?.querySelector(`[data-key="${key}"] .cancel-upload`);
    if (cancelButton && cancelButton === document.activeElement) pendingFocus.current = { key, control };
  };

  const startUpload = (key: number, file: File) => {
    const controller = new AbortController();
    controllers.current.set(key, controller);
    update(key, { status: 'uploading', percent: 0 });
    uploadReceipt(file, { signal: controller.signal, onProgress: (percent) => update(key, { percent }) })
      .then(() => {
        keepFocusAfterEnd(key, 'remove');
        update(key, { status: 'uploaded', percent: 100 });
      })
      .catch(() => {
        // A cancel has already marked the row, and a remove has dropped it.
        if (controller.signal.aborted) return;
        keepFocusAfterEnd(key, 'retry');
        update(key, { status: 'failed' });
      })
      .finally(() => {
        if (controllers.current.get(key) === controller) controllers.current.delete(key);
      });
  };

  const stopUpload = (key: number) => {
    controllers.current.get(key)?.abort();
    controllers.current.delete(key);
  };

  const addFiles = (files: FileList | null) => {
    const accepted: Upload[] = [];
    const problems: string[] = [];
    for (const file of Array.from(files ?? [])) {
      const problem = rejectionOf(file);
      if (problem) {
        problems.push(problem);
        continue;
      }
      const key = nextKey.current;
      nextKey.current += 1;
      // One URL per file, made here rather than in render, so re-renders reuse it.
      const previewUrl = URL.createObjectURL(file);
      previewUrls.current.set(key, previewUrl);
      accepted.push({ key, file, previewUrl, status: 'uploading', percent: 0 });
    }
    setRejections(problems.map((text) => ({ id: nextRejection.current++, text })));
    setUploads((current) => [...current, ...accepted]);
    accepted.forEach((upload) => startUpload(upload.key, upload.file));
  };

  const cancel = (key: number) => {
    stopUpload(key);
    // An upload that finished just before the click stays Uploaded.
    setUploads((current) =>
      current.map((upload) =>
        upload.key === key && upload.status === 'uploading' ? { ...upload, status: 'cancelled' } : upload,
      ),
    );
    pendingFocus.current = { key, control: 'retry' };
  };

  const retry = (upload: Upload) => {
    startUpload(upload.key, upload.file);
    pendingFocus.current = { key: upload.key, control: 'cancel-upload' };
  };

  const remove = (key: number) => {
    const index = uploads.findIndex((upload) => upload.key === key);
    const neighbour = uploads[index + 1] ?? uploads[index - 1];
    pendingFocus.current = neighbour ? { key: neighbour.key, control: 'remove' } : 'choose';
    stopUpload(key);
    const url = previewUrls.current.get(key);
    if (url) URL.revokeObjectURL(url);
    previewUrls.current.delete(key);
    setUploads((current) => current.filter((upload) => upload.key !== key));
  };

  // Moving onto a child fires dragenter on the child before dragleave on the zone, so the zone counts enters and
  // leaves instead of switching off on the first leave.
  const handleDragEnter = (event: React.DragEvent<HTMLDivElement>) => {
    if (!carriesFiles(event.dataTransfer)) return;
    event.preventDefault();
    dragDepth.current += 1;
    setDragActive(true);
  };

  // Leaves are not filtered: a text drag never raised the count, and the floor of zero keeps it there.
  const handleDragLeave = () => {
    dragDepth.current = Math.max(0, dragDepth.current - 1);
    if (dragDepth.current === 0) setDragActive(false);
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    if (!carriesFiles(event.dataTransfer)) return;
    // Without this, the browser does not allow a drop here.
    event.preventDefault();
    event.dataTransfer.dropEffect = 'copy';
  };

  const handleDrop = (event: React.DragEvent<HTMLDivElement>) => {
    if (!carriesFiles(event.dataTransfer)) return;
    event.preventDefault();
    dragDepth.current = 0;
    setDragActive(false);
    addFiles(event.dataTransfer.files);
  };

  return (
    <main className="page">
      <section className="card">
        <header className="card-header">
          <h1 className="title">Receipts</h1>
          <p className="subtitle">Expense report · Spring offsite</p>
        </header>

        <div
          ref={zoneRef}
          className="dropzone"
          data-active={dragActive ? 'true' : undefined}
          onDragEnter={handleDragEnter}
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          <p className="dropzone-hint">Drop receipts here</p>
          <p className="dropzone-note">PNG or JPEG, up to 2 MB each</p>
          <button ref={chooseRef} type="button" className="choose" onClick={() => inputRef.current?.click()}>
            Choose files
          </button>
          <input
            ref={inputRef}
            className="picker"
            type="file"
            accept={ACCEPTED_TYPES.join(',')}
            multiple
            hidden
            onChange={(event) => {
              addFiles(event.target.files);
              // Clearing the value lets the same file be chosen again.
              event.target.value = '';
            }}
          />
        </div>

        <ul className="rejections" aria-live="polite">
          {/* New ids for every batch, so a repeated message is a new node that screen readers announce again. */}
          {rejections.map((rejection) => (
            <li key={rejection.id}>{rejection.text}</li>
          ))}
        </ul>

        <ul className="uploads" ref={listRef}>
          {uploads.map((upload) => {
            const name = upload.file.name;
            const stopped = upload.status === 'failed' || upload.status === 'cancelled';
            const statusText =
              upload.status === 'uploading' ? `Uploading ${upload.percent}%` : STATUS_TEXT[upload.status];
            // A stopped row keeps its percent; say it, since aria-valuetext replaces the number for screen readers.
            const valueText = stopped ? `${statusText} at ${upload.percent}%` : statusText;
            return (
              <li className="upload" key={upload.key} data-key={upload.key}>
                <img className="thumb" src={upload.previewUrl} alt="" draggable={false} />
                <div className="upload-body">
                  <span className="upload-name">{name}</span>
                  <div
                    className="progress"
                    role="progressbar"
                    aria-label={`Upload of ${name}`}
                    aria-valuemin={0}
                    aria-valuemax={100}
                    aria-valuenow={upload.percent}
                    aria-valuetext={valueText}
                  >
                    <div className="progress-fill" style={{ width: `${upload.percent}%` }} />
                  </div>
                  <span className="upload-status">{statusText}</span>
                </div>
                <div className="upload-actions">
                  {upload.status === 'uploading' && (
                    <button
                      type="button"
                      className="cancel-upload"
                      aria-label={`Cancel the upload of ${name}`}
                      onClick={() => cancel(upload.key)}
                    >
                      Cancel
                    </button>
                  )}
                  {stopped && (
                    <button
                      type="button"
                      className="retry"
                      aria-label={`Retry the upload of ${name}`}
                      onClick={() => retry(upload)}
                    >
                      Retry
                    </button>
                  )}
                  <button
                    type="button"
                    className="remove"
                    aria-label={`Remove ${name}`}
                    onClick={() => remove(upload.key)}
                  >
                    Remove
                  </button>
                </div>
              </li>
            );
          })}
        </ul>
      </section>
    </main>
  );
}

import React, { createContext, useContext, useEffect, useLayoutEffect, useState } from 'react';
import './App.css';

export type Role = 'viewer' | 'support' | 'lead' | 'admin';
export type Permission =
  | 'tickets:read'
  | 'refunds:read'
  | 'refunds:write'
  | 'users:read'
  | 'users:write'
  | 'settings:write'
  | 'audit:read';

/** Given: what each role may do. */
export const ROLE_PERMISSIONS: Record<Role, readonly Permission[]> = {
  viewer: ['tickets:read'],
  support: ['tickets:read', 'refunds:read', 'users:read'],
  lead: ['tickets:read', 'refunds:read', 'refunds:write', 'users:read'],
  admin: [
    'tickets:read',
    'refunds:read',
    'refunds:write',
    'users:read',
    'users:write',
    'settings:write',
    'audit:read',
  ],
};

export interface RouteDef {
  /** A path pattern. A segment that starts with ":" matches any non-empty segment, such as the 42 of /tickets/42. */
  path: string;
  title: string;
  /** The page's name: its key in PAGES and in the load counters. */
  page: string;
  /** What a user needs to open the page; null means any signed-in user. */
  permission: Permission | null;
  /** The page has a sidebar link. */
  nav?: boolean;
  /** For a page below a sidebar link, that link's path. */
  section?: string;
}

/** Given: every page of the console. /sign-in is not in it: signed-out users open it without a permission. */
export const ROUTES: readonly RouteDef[] = [
  { path: '/', title: 'Dashboard', page: 'dashboard', permission: null, nav: true },
  { path: '/tickets', title: 'Tickets', page: 'tickets', permission: 'tickets:read', nav: true },
  { path: '/tickets/:id', title: 'Ticket', page: 'ticket', permission: 'tickets:read', section: '/tickets' },
  { path: '/refunds', title: 'Refunds', page: 'refunds', permission: 'refunds:read', nav: true },
  { path: '/refunds/new', title: 'New refund', page: 'new-refund', permission: 'refunds:write', section: '/refunds' },
  { path: '/users', title: 'Users', page: 'users', permission: 'users:read', nav: true },
  { path: '/users/:id/edit', title: 'Edit user', page: 'edit-user', permission: 'users:write', section: '/users' },
  { path: '/settings', title: 'Settings', page: 'settings', permission: 'settings:write', nav: true },
  { path: '/audit-log', title: 'Audit log', page: 'audit-log', permission: 'audit:read', nav: true },
];

export interface Session {
  userId: number;
  name: string;
  role: Role;
}

/** Time each call to the fake server takes, in ms. */
export const SERVER_DELAY_MS = 500;

const SESSION_KEY = 'console-session';
const accounts: Session[] = [
  { userId: 1, name: 'Ana', role: 'admin' },
  { userId: 2, name: 'Sam', role: 'support' },
  { userId: 3, name: 'Vic', role: 'viewer' },
  { userId: 4, name: 'Lee', role: 'lead' },
];
const readStoredUser = () => {
  try {
    return Number(localStorage.getItem(SESSION_KEY)) || null;
  } catch {
    return null;
  }
};
const storeUser = (userId: number | null) => {
  try {
    if (userId === null) localStorage.removeItem(SESSION_KEY);
    else localStorage.setItem(SESSION_KEY, String(userId));
  } catch {
    // The preview may have no storage; the session then lasts until it reloads.
  }
};
const roleOf = (userId: number | null) => accounts.find((candidate) => candidate.userId === userId)?.role ?? null;
let signedInUser = readStoredUser();
/** The role the session carries; a saved change reaches it 2 × SERVER_DELAY_MS after the save. */
let sessionRole = roleOf(signedInUser);
const sessionListeners = new Set<(session: Session | null) => void>();
const currentSession = (): Session | null => {
  const account = accounts.find((candidate) => candidate.userId === signedInUser);
  return account && sessionRole ? { userId: account.userId, name: account.name, role: sessionRole } : null;
};
const tellSessionListeners = () => {
  const session = currentSession();
  sessionListeners.forEach((listener) => listener(session));
};
const later = <T,>(work: () => T) =>
  new Promise<T>((resolve) => {
    window.setTimeout(() => resolve(work()), SERVER_DELAY_MS);
  });

/** Given: the session the server remembers for this browser, or null when nobody is signed in. */
export function fetchSession(): Promise<Session | null> {
  return later(currentSession);
}

/** Given: signs in as a demo account, tells every onSessionChange listener, then resolves with the session. */
export function signIn(userId: number): Promise<Session | null> {
  return later(() => {
    signedInUser = userId;
    sessionRole = roleOf(userId);
    storeUser(userId);
    tellSessionListeners();
    return currentSession();
  });
}

/** Given: signs out, then tells every onSessionChange listener. */
export function signOut(): Promise<void> {
  return later(() => {
    signedInUser = null;
    sessionRole = null;
    storeUser(null);
    tellSessionListeners();
  });
}

/**
 * Given: saves a user's role. When that user is the one signed in, the session picks the new role up
 * 2 × SERVER_DELAY_MS after the save resolves, as when a token is refreshed, and then tells every onSessionChange
 * listener; until then fetchSession still reports the old role.
 */
export function updateUserRole(userId: number, role: Role): Promise<void> {
  return later(() => {
    const account = accounts.find((candidate) => candidate.userId === userId);
    if (!account) return;
    account.role = role;
    if (userId !== signedInUser) return;
    window.setTimeout(() => {
      if (userId !== signedInUser) return;
      sessionRole = role;
      tellSessionListeners();
    }, 2 * SERVER_DELAY_MS);
  });
}

/** Given: the demo accounts with their current roles. */
export function getAccounts(): Session[] {
  return accounts.map((account) => ({ ...account }));
}

/**
 * Given: calls the listener with the new session (null when signed out) whenever the signed-in user or their role
 * changes, and returns a function that stops it. body[data-session-listeners] shows how many listeners are active.
 */
export function onSessionChange(listener: (session: Session | null) => void): () => void {
  sessionListeners.add(listener);
  document.body.dataset.sessionListeners = String(sessionListeners.size);
  return () => {
    sessionListeners.delete(listener);
    document.body.dataset.sessionListeners = String(sessionListeners.size);
  };
}

export type LocationState = Record<string, string> | null;

export interface Location {
  path: string;
  state: LocationState;
  /** A new key for every entry, even when the path repeats. */
  key: number;
}

/**
 * Given: an in-memory history that stands in for the browser's, because the preview has no address bar. push adds
 * an entry after the current one, replace swaps the current entry, back returns to the previous one. It starts at /.
 * body[data-history-listeners] shows how many listeners are active.
 */
const entries: Location[] = [{ path: '/', state: null, key: 0 }];
let currentEntry = 0;
let nextKey = 1;
const historyListeners = new Set<() => void>();
const tellHistoryListeners = () => historyListeners.forEach((listener) => listener());
export const history = {
  getLocation: (): Location => entries[currentEntry],
  canGoBack: () => currentEntry > 0,
  push: (path: string, state: LocationState = null) => {
    entries.splice(currentEntry + 1, entries.length, { path, state, key: nextKey++ });
    currentEntry = entries.length - 1;
    tellHistoryListeners();
  },
  replace: (path: string, state: LocationState = null) => {
    entries[currentEntry] = { path, state, key: nextKey++ };
    tellHistoryListeners();
  },
  back: () => {
    if (currentEntry === 0) return;
    currentEntry -= 1;
    tellHistoryListeners();
  },
  listen: (listener: () => void) => {
    historyListeners.add(listener);
    document.body.dataset.historyListeners = String(historyListeners.size);
    return () => {
      historyListeners.delete(listener);
      document.body.dataset.historyListeners = String(historyListeners.size);
    };
  },
};

/** Given: the current history entry; the component renders again when it changes. */
export function useLocation(): Location {
  const [location, setLocation] = useState(history.getLocation);
  useEffect(() => {
    // Catches an entry added between the first render and this subscription.
    setLocation(history.getLocation());
    return history.listen(() => setLocation(history.getLocation()));
  }, []);
  return location;
}

export interface LinkProps {
  to: string;
  className?: string;
  children?: React.ReactNode;
  'aria-current'?: 'page';
  'aria-label'?: string;
}

/** Given: a link that opens its page through history.push instead of loading a new document. */
export function Link({ to, children, ...rest }: LinkProps) {
  return (
    <a
      {...rest}
      href={to}
      onClick={(event) => {
        event.preventDefault();
        history.push(to);
      }}
    >
      {children}
    </a>
  );
}

/** Given: the preview's address bar. Type a path and press Enter or Go to open it; ← goes back. */
export function AddressBar() {
  const location = useLocation();
  const [draft, setDraft] = useState(location.path);
  // Shows each new entry's path; set during render, so nothing resets what was typed before the first effects run.
  const [shownKey, setShownKey] = useState(location.key);
  if (shownKey !== location.key) {
    setShownKey(location.key);
    setDraft(location.path);
  }
  const open = () => {
    const path = draft.trim();
    if (path.startsWith('/')) history.push(path);
  };
  return (
    <div className="address-bar">
      <button
        type="button"
        className="back"
        aria-label="Back"
        disabled={!history.canGoBack()}
        onClick={history.back}
      >
        ←
      </button>
      <input
        className="address"
        aria-label="Address"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={(event) => {
          if (event.key === 'Enter') open();
        }}
      />
      <button type="button" className="go" onClick={open}>
        Go
      </button>
    </div>
  );
}

/**
 * Given: stands in for loading a page's data. Each page calls it once, first thing; it counts the page's loads on
 * body[data-loads-<page>], such as data-loads-settings, so the checks can tell which pages rendered.
 */
const pageLoads = new Map<string, number>(ROUTES.map((route) => [route.page, 0]));
const showPageLoads = () =>
  pageLoads.forEach((count, page) => document.body.setAttribute(`data-loads-${page}`, String(count)));
showPageLoads();
document.body.dataset.sessionListeners = '0';
document.body.dataset.historyListeners = '0';
export function usePageLoad(page: string) {
  useEffect(() => {
    pageLoads.set(page, (pageLoads.get(page) ?? 0) + 1);
    showPageLoads();
  }, [page]);
}

interface PageProps {
  params: Record<string, string>;
}

type SessionState = { status: 'loading' } | { status: 'ready'; session: Session | null };

/** One rule for the sidebar, the pages' own links and the guard; with nobody signed in, nothing is allowed. */
const can = (session: Session | null, permission: Permission | null) =>
  session !== null && (permission === null || ROLE_PERMISSIONS[session.role].includes(permission));

const SessionContext = createContext<SessionState>({ status: 'loading' });
const NoticeContext = createContext<(title: string) => void>(() => undefined);
const useCan = () => {
  const state = useContext(SessionContext);
  return (permission: Permission) => can(state.status === 'ready' ? state.session : null, permission);
};

/** Compares whole segments as they are: /refunds/new is not /refunds, and /users-export or /tickets/ is no page. */
function matchRoute(path: string): { route: RouteDef; params: Record<string, string> } | null {
  const segments = path.split('/').slice(1);
  for (const route of ROUTES) {
    const pattern = route.path.split('/').slice(1);
    if (pattern.length !== segments.length) continue;
    const params: Record<string, string> = {};
    const matches = pattern.every((part, index) => {
      if (!part.startsWith(':')) return part === segments[index];
      params[part.slice(1)] = segments[index];
      return segments[index] !== '';
    });
    if (matches) return { route, params };
  }
  return null;
}

/**
 * Replaces the current entry, so Back skips the page it refused. A layout effect does it after the commit and before
 * the browser paints, so no empty frame shows on the way.
 */
function Redirect({ to, from, denied }: { to: string; from?: string; denied?: string }) {
  const showNotice = useContext(NoticeContext);
  useLayoutEffect(() => {
    history.replace(to, from === undefined ? null : { from });
    // After the replace, whose history listener has just cleared any older notice.
    if (denied !== undefined) showNotice(denied);
  }, [to, from, denied, showNotice]);
  return null;
}

function SessionLoading() {
  return (
    <p className="page-loading" role="status">
      Loading your session…
    </p>
  );
}

/** Every page goes through here. It waits for the session, and a refused page never renders or loads its data. */
function RequireAccess(props: { route: RouteDef | null; path: string; children: React.ReactNode }) {
  const { route, path, children } = props;
  const state = useContext(SessionContext);
  if (state.status === 'loading') return <SessionLoading />;
  if (state.session === null) return <Redirect to="/sign-in" from={path} />;
  if (route && !can(state.session, route.permission)) return <Redirect to="/" denied={route.title} />;
  return <>{children}</>;
}

/** /sign-in waits for the session too; a signed-in user goes where this entry points, or to the Dashboard. */
function SignInRoute({ from }: { from?: string }) {
  const state = useContext(SessionContext);
  if (state.status !== 'ready') return <SessionLoading />;
  if (state.session) return <Redirect to={from ?? '/'} />;
  return <SignInPage />;
}

export default function App() {
  const location = useLocation();
  const [state, setState] = useState<SessionState>({ status: 'loading' });
  const [notice, setNotice] = useState<string | null>(null);

  useEffect(() => {
    let active = true;
    const stop = onSessionChange((session) => setState({ status: 'ready', session }));
    fetchSession().then((session) => {
      // A change the listener reported while the request was out is newer than this answer. The fake server cannot
      // produce one, since nothing can change the session before the console has loaded it, but a real one can.
      if (active) setState((current) => (current.status === 'loading' ? { status: 'ready', session } : current));
    });
    return () => {
      active = false;
      stop();
    };
  }, []);

  // Any navigation, Back included, ends the notice; a refusing redirect sets it again right after its replace.
  useEffect(() => history.listen(() => setNotice(null)), []);

  const session = state.status === 'ready' ? state.session : null;
  const match = matchRoute(location.path);
  const current = match ? (match.route.section ?? match.route.path) : null;

  const Page = match ? PAGES[match.route.page] : NotFoundPage;
  const content =
    location.path === '/sign-in' ? (
      <SignInRoute from={location.state?.from} />
    ) : (
      <RequireAccess route={match ? match.route : null} path={location.path}>
        {notice && (
          <p className="access-notice" role="status">
            You don't have access to the {notice} page.
          </p>
        )}
        <Page key={location.path} params={match ? match.params : {}} />
      </RequireAccess>
    );

  return (
    <SessionContext.Provider value={state}>
      <NoticeContext.Provider value={setNotice}>
        <div className="console">
          <AddressBar />
          <header className="topbar">
            <span className="brand">Support console</span>
            {session && (
              <>
                <span className="account">
                  {session.name} · {session.role}
                </span>
                <button type="button" className="sign-out" onClick={() => signOut()}>
                  Sign out
                </button>
              </>
            )}
          </header>
          <div className="frame">
            <nav className="sidebar" aria-label="Sections">
              {ROUTES.filter((route) => route.nav && can(session, route.permission)).map((route) => (
                <Link
                  key={route.path}
                  className="nav-link"
                  to={route.path}
                  aria-current={route.path === current ? 'page' : undefined}
                >
                  {route.title}
                </Link>
              ))}
            </nav>
            <main className="content">{content}</main>
          </div>
        </div>
      </NoticeContext.Provider>
    </SessionContext.Provider>
  );
}

