/** Given: the TV's browser is old and has no IntersectionObserver. */
Reflect.deleteProperty(window, 'IntersectionObserver');

const setRequests = new Map<string, number>(Object.keys(SETS).map((setId) => [setId, 0]));
const showSetRequests = () =>
  setRequests.forEach((count, setId) => document.body.setAttribute(`data-set-${setId}`, String(count)));
showSetRequests();

/** Given: the home document, after HOME_DELAY_MS. */
export function fetchHome(): Promise<HomeDocument> {
  return new Promise((resolve) => {
    window.setTimeout(() => resolve(HOME), HOME_DELAY_MS);
  });
}

/**
 * Given: the titles of one set, after SET_DELAY_MS. It counts the requests for each set on
 * body[data-set-<setId>], such as data-set-docs, so the checks can tell which sets were asked for.
 */
export function fetchSet(setId: string): Promise<Title[]> {
  setRequests.set(setId, (setRequests.get(setId) ?? 0) + 1);
  showSetRequests();
  return new Promise((resolve) => {
    window.setTimeout(() => resolve(SETS[setId] ?? []), SET_DELAY_MS);
  });
}

/** The focused row, and the column the user last chose with Left or Right. */
interface Focus {
  row: number;
  column: number;
}

/** Each arrow as [rows down, tiles across]. */
const ARROWS = new Map<string, [number, number]>([
  ['ArrowUp', [-1, 0]],
  ['ArrowDown', [1, 0]],
  ['ArrowLeft', [0, -1]],
  ['ArrowRight', [0, 1]],
]);
const isBack = (key: string) => key === 'Escape' || key === 'Backspace';
/** Rows from the focused one to this many below it are on screen. */
const ROWS_AHEAD = 2;

function Tile(props: { item: Title; tileRef: (element: HTMLElement | null) => void; onOpen: () => void }) {
  const { item, tileRef, onOpen } = props;
  const [broken, setBroken] = useState(false);
  return (
    <button ref={tileRef} type="button" className="tile" onClick={onOpen}>
      {broken ? (
        <span className="tile-fallback">{item.name}</span>
      ) : (
        <img className="tile-image" src={item.image} alt={item.name} onError={() => setBroken(true)} />
      )}
    </button>
  );
}

export default function App() {
  const [home, setHome] = useState<HomeDocument | null>(null);
  const [sets, setSets] = useState<Record<string, Title[]>>({});
  const [focus, setFocus] = useState<Focus>({ row: 0, column: 0 });
  const [details, setDetails] = useState<Title | null>(null);
  const [detailsButton, setDetailsButton] = useState(0);
  const [playing, setPlaying] = useState(false);
  const [watchlist, setWatchlist] = useState<string[]>([]);
  const requested = useRef(new Set<string>());
  const elements = useRef(new Map<string, HTMLElement>());
  const refCallbacks = useRef(new Map<string, (element: HTMLElement | null) => void>());

  useEffect(() => {
    fetchHome().then(setHome);
  }, []);

  /** A row's titles, or undefined while it loads; a set that came back empty has nothing to focus either. */
  const itemsOf = (row: HomeRow) => {
    const items = row.kind === 'curated' ? row.items : sets[row.setId];
    return items && items.length > 0 ? items : undefined;
  };

  // Without IntersectionObserver, focus decides what counts as in view: the focused row and the two below it, the
  // rows the remote reaches next.
  useEffect(() => {
    if (!home) return;
    home.rows.slice(focus.row, focus.row + ROWS_AHEAD + 1).forEach((row) => {
      if (row.kind !== 'set' || requested.current.has(row.setId)) return;
      requested.current.add(row.setId);
      fetchSet(row.setId).then((items) => setSets((current) => ({ ...current, [row.setId]: items })));
    });
  }, [home, focus.row]);

  const focusedRow = home ? home.rows[focus.row] : undefined;
  const focusedItems = focusedRow ? itemsOf(focusedRow) : undefined;
  // A shorter row clamps the column for display only; the column itself is kept for the rows after it.
  const focusedIndex = focusedItems ? Math.min(focus.column, focusedItems.length - 1) : -1;
  const focusKey = !home
    ? ''
    : details
      ? `details:${detailsButton}`
      : focusedItems
        ? `${focus.row}:${focusedIndex}`
        : `${focus.row}:placeholder`;

  // Moves DOM focus whenever its target changes, including when a loading row's titles arrive.
  useEffect(() => {
    elements.current.get(focusKey)?.focus();
  }, [focusKey]);

  // One stable callback ref per key, so a render does not detach and reattach every tile.
  const register = (key: string) => {
    let callback = refCallbacks.current.get(key);
    if (!callback) {
      callback = (element: HTMLElement | null) => {
        if (element) elements.current.set(key, element);
        else elements.current.delete(key);
      };
      refCallbacks.current.set(key, callback);
    }
    return callback;
  };

  const openDetails = (row: number, column: number, item: Title) => {
    // Enter opens the focused tile, so the kept column stays; a click elsewhere in the preview moves focus there.
    if (row !== focus.row || column !== focusedIndex) setFocus({ row, column });
    setDetails(item);
    setDetailsButton(0);
    setPlaying(false);
  };

  useEffect(() => {
    if (!home) return;
    const onKeyDown = (event: KeyboardEvent) => {
      // A held key repeats; a repeated Enter would press the button that the first one just focused.
      if (event.key === 'Enter' && event.repeat) {
        event.preventDefault();
        return;
      }
      // A click on empty space drops DOM focus; any key brings it back to the element the state names.
      const target = elements.current.get(focusKey);
      if (target && document.activeElement !== target) target.focus();
      if (details) {
        // The details trap the remote: arrows move between their buttons, and Back closes them.
        const arrow = ARROWS.get(event.key);
        if (isBack(event.key)) {
          event.preventDefault();
          setDetails(null);
        } else if (arrow) {
          event.preventDefault();
          if (arrow[1] !== 0) setDetailsButton(arrow[1] < 0 ? 0 : 1);
        }
        return;
      }
      // An old TV browser goes back a page on Backspace.
      if (event.key === 'Backspace') event.preventDefault();
      const arrow = ARROWS.get(event.key);
      if (!arrow) return;
      event.preventDefault();
      const [down, across] = arrow;
      if (down !== 0) {
        const row = Math.max(0, Math.min(home.rows.length - 1, focus.row + down));
        setFocus({ row, column: focus.column });
      } else if (focusedItems) {
        const column = Math.max(0, Math.min(focusedItems.length - 1, focusedIndex + across));
        // A press against the end of a row moves nothing, so it chooses no column either.
        if (column !== focusedIndex) setFocus({ row: focus.row, column });
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  }, [home, details, focus, focusedItems, focusedIndex, focusKey]);

  if (!home) {
    return (
      <main className="home">
        <p className="home-loading" role="status">
          Loading…
        </p>
      </main>
    );
  }

  const onList = details ? watchlist.includes(details.id) : false;
  const toggleWatchlist = (id: string) =>
    setWatchlist((current) => (current.includes(id) ? current.filter((item) => item !== id) : [...current, id]));

  return (
    <main className="home">
      <div className="rows">
        {home.rows.map((row, rowIndex) => {
          const items = itemsOf(row);
          return (
            <section key={row.id} className="row" data-row={row.id}>
              <h2 className="row-title">{row.title}</h2>
              <div className="row-tiles">
                {items ? (
                  items.map((item, column) => (
                    <Tile
                      key={item.id}
                      item={item}
                      tileRef={register(`${rowIndex}:${column}`)}
                      onOpen={() => openDetails(rowIndex, column, item)}
                    />
                  ))
                ) : (
                  <div ref={register(`${rowIndex}:placeholder`)} className="row-placeholder" tabIndex={-1}>
                    {row.kind === 'curated' || sets[row.setId] ? 'No titles' : 'Loading…'}
                  </div>
                )}
              </div>
            </section>
          );
        })}
      </div>

      {details && (
        <div className="details-backdrop" onClick={() => setDetails(null)}>
          <div
            className="details"
            role="dialog"
            aria-modal="true"
            aria-labelledby="details-title"
            onClick={(event) => event.stopPropagation()}
          >
            <h2 id="details-title" className="details-title">
              {details.name}
            </h2>
            <p className="details-year">{details.year}</p>
            <p className="details-description">{details.description}</p>
            <div className="details-actions">
              <button
                ref={register('details:0')}
                type="button"
                className="play"
                onClick={() => {
                  setDetailsButton(0);
                  setPlaying(true);
                }}
              >
                Play
              </button>
              <button
                ref={register('details:1')}
                type="button"
                className="watchlist"
                aria-pressed={onList}
                onClick={() => {
                  setDetailsButton(1);
                  toggleWatchlist(details.id);
                }}
              >
                My list
              </button>
            </div>
            <p className="details-status" role="status">
              {playing ? `Playing ${details.name}` : ''}
            </p>
          </div>
        </div>
      )}
    </main>
  );
}

import React, { useEffect, useMemo, useRef, useState } from 'react';
import './App.css';

// ---------------------------------------------------------------------------------------------------------------
// Given: the speech service's types and a fake implementation. Read the types; treat everything down to Studio as
// given and working.
// ---------------------------------------------------------------------------------------------------------------

export type VoiceId = string;

export interface Voice {
  id: VoiceId;
  name: string;
  /** The longest text this voice accepts, in characters. */
  maxCharacters: number;
}

export interface Clip {
  voiceId: VoiceId;
  /** The text the clip speaks. */
  text: string;
  /** Length of the audio in seconds. */
  seconds: number;
}

export type SpeechErrorCode = 'quota-exceeded' | 'text-rejected' | 'service-unavailable';

/**
 * Every failure the service reports is a SpeechError; a job stopped through its signal rejects with an AbortError
 * instead. A SpeechError's `message` is a code for logs, not for people.
 */
export class SpeechError extends Error {
  readonly code: SpeechErrorCode;

  constructor(code: SpeechErrorCode) {
    super(`speech_error:${code}`);
    this.name = 'SpeechError';
    this.code = code;
  }
}

/** What people should read for each failure. */
export const ERROR_MESSAGES: Record<SpeechErrorCode, string> = {
  'quota-exceeded': "You have used this month's characters.",
  'text-rejected': "This text can't be voiced. Edit it and try again.",
  'service-unavailable': 'The voice service is unavailable. Try again in a moment.',
};

export interface SynthesisOptions {
  /**
   * Aborting stops the job: its timers stop, `onProgress` is not called again, and the promise rejects with a
   * DOMException named 'AbortError'.
   */
  signal: AbortSignal;
  /** Called with 10, 20, … 100 as the job runs. */
  onProgress: (percent: number) => void;
}

export interface SpeechService {
  /** Resolves with the voices after 300 ms. Rejects with a SpeechError when the service is down. */
  listVoices(): Promise<Voice[]>;
  /**
   * Voices `text` with the voice. Resolves with the clip after progress reaches 100. Rejects with a SpeechError when
   * the job fails, or with an AbortError once it is stopped through `options.signal`.
   */
  synthesize(text: string, voiceId: VoiceId, options: SynthesisOptions): Promise<Clip>;
}

export type Scenario = 'normal' | 'slow' | 'voices-down' | 'quota' | 'rejected';

const VOICES: Voice[] = [
  { id: 'rowan', name: 'Rowan · narration', maxCharacters: 200 },
  { id: 'ines', name: 'Inès · conversational', maxCharacters: 120 },
  { id: 'kit', name: 'Kit · short form', maxCharacters: 40 },
];

/**
 * A fake service for one scenario. Progress moves every 100 ms (every 300 ms when slow). With 'voices-down' the
 * first listVoices fails and later ones answer; with 'quota' and 'rejected' a job fails after 30 %.
 */
export function createSpeechService(scenario: Scenario): SpeechService {
  let voiceCalls = 0;
  const every = scenario === 'slow' ? 300 : 100;
  return {
    listVoices() {
      voiceCalls += 1;
      const fail = scenario === 'voices-down' && voiceCalls === 1;
      return new Promise((resolve, reject) => {
        window.setTimeout(() => {
          if (fail) reject(new SpeechError('service-unavailable'));
          else resolve(VOICES.map((voice) => ({ ...voice })));
        }, 300);
      });
    },
    synthesize(text, voiceId, { signal, onProgress }) {
      return new Promise((resolve, reject) => {
        const abortError = () => new DOMException('The job was cancelled.', 'AbortError');
        if (signal.aborted) {
          reject(abortError());
          return;
        }
        const voice = VOICES.find((candidate) => candidate.id === voiceId);
        let percent = 0;
        const stop = () => {
          window.clearInterval(timer);
          signal.removeEventListener('abort', onAbort);
        };
        const onAbort = () => {
          stop();
          reject(abortError());
        };
        const timer = window.setInterval(() => {
          if (percent === 30 && (scenario === 'quota' || scenario === 'rejected')) {
            stop();
            reject(new SpeechError(scenario === 'quota' ? 'quota-exceeded' : 'text-rejected'));
            return;
          }
          if (!voice || text.trim() === '' || text.length > voice.maxCharacters) {
            stop();
            reject(new SpeechError('text-rejected'));
            return;
          }
          percent += 10;
          onProgress(percent);
          if (percent === 100) {
            stop();
            resolve({ voiceId, text, seconds: Math.max(1, Math.round(text.length / 14)) });
          }
        }, every);
        signal.addEventListener('abort', onAbort);
      });
    },
  };
}

export type PanelStatus = 'loading-voices' | 'voices-failed' | 'idle' | 'generating' | 'done' | 'failed';

export interface SpeakerPanelProps {
  status: PanelStatus;
  /** Empty until the voices load. */
  voices: Voice[];
  voiceId: VoiceId | null;
  text: string;
  /** The job's last reported percentage while generating; null otherwise. */
  progress: number | null;
  clip: Clip | null;
  /** A message for people, shown whenever it is not null. */
  error: string | null;
  /** Generate is disabled when this is false. */
  canGenerate: boolean;
  onVoiceChange: (voiceId: VoiceId) => void;
  onTextChange: (text: string) => void;
  onGenerate: () => void;
  onCancel: () => void;
  onRetryVoices: () => void;
}

const STATUS_TEXT: Record<PanelStatus, string> = {
  'loading-voices': 'Loading voices…',
  'voices-failed': 'Voices unavailable',
  idle: 'Ready',
  generating: 'Generating…',
  done: 'Done',
  failed: 'Failed',
};

/** Given and working: it renders what its props say and reports what the user does. */
export function SpeakerPanel(props: SpeakerPanelProps) {
  const voice = props.voices.find((candidate) => candidate.id === props.voiceId) ?? null;
  const clipVoice = props.clip ? props.voices.find((candidate) => candidate.id === props.clip?.voiceId) : null;
  return (
    <section className="panel" aria-label="Speech studio">
      <p className="status" role="status">
        {STATUS_TEXT[props.status]}
      </p>
      {props.status === 'generating' && props.progress !== null && (
        <p className="progress" data-percent={props.progress}>
          {props.progress}%
        </p>
      )}
      {props.error !== null && (
        <p className="error" role="alert">
          {props.error}
        </p>
      )}
      {props.status === 'voices-failed' && (
        <button type="button" className="retry-voices" onClick={props.onRetryVoices}>
          Load voices again
        </button>
      )}
      <label className="field">
        <span className="field-label">Voice</span>
        <select
          className="voice"
          value={props.voiceId ?? ''}
          disabled={props.voices.length === 0}
          onChange={(event) => props.onVoiceChange(event.target.value)}
        >
          {props.voices.map((candidate) => (
            <option key={candidate.id} value={candidate.id}>
              {candidate.name}
            </option>
          ))}
        </select>
      </label>
      <label className="field">
        <span className="field-label">Text</span>
        <textarea className="text" rows={4} value={props.text} onChange={(event) => props.onTextChange(event.target.value)} />
      </label>
      <p className={voice && props.text.length > voice.maxCharacters ? 'char-count over' : 'char-count'}>
        {props.text.length} / {voice ? voice.maxCharacters : '—'}
      </p>
      <div className="actions">
        <button type="button" className="generate" disabled={!props.canGenerate} onClick={props.onGenerate}>
          Generate
        </button>
        {props.status === 'generating' && (
          <button type="button" className="cancel" onClick={props.onCancel}>
            Cancel
          </button>
        )}
      </div>
      {props.clip && (
        <figure className="clip">
          <figcaption className="clip-voice">{clipVoice ? clipVoice.name : props.clip.voiceId}</figcaption>
          <blockquote className="clip-text">{props.clip.text}</blockquote>
          <span className="clip-seconds">{props.clip.seconds} s</span>
        </figure>
      )}
    </section>
  );
}

