import React, { useEffect, useRef, useState } from 'react';
import './App.css';

/** The sheet's columns, A to N, and its ten rows. */
export const COLUMNS = 'ABCDEFGHIJKLMN'.split('');
export const ROW_COUNT = 10;

/** A cell by its 0-based column and row. */
export interface Cell {
  col: number;
  row: number;
}

/** "B2": the name a cell shows and carries in `data-cell`. */
export function cellName(cell: Cell): string {
  return `${COLUMNS[cell.col]}${cell.row + 1}`;
}

type Selection = { anchor: Cell; focus: Cell };

const clamp = (value: number, max: number) => Math.max(0, Math.min(value, max));

/** The selected rectangle's corners, top left first, whichever way it was drawn. */
function bounds({ anchor, focus }: Selection) {
  return {
    top: Math.min(anchor.row, focus.row),
    bottom: Math.max(anchor.row, focus.row),
    left: Math.min(anchor.col, focus.col),
    right: Math.max(anchor.col, focus.col),
  };
}

function summary(selection: Selection | null): string {
  if (!selection) return 'No cells selected';
  const { top, bottom, left, right } = bounds(selection);
  const count = (bottom - top + 1) * (right - left + 1);
  const first = cellName({ col: left, row: top });
  if (count === 1) return `${first} · 1 cell`;
  return `${first}:${cellName({ col: right, row: bottom })} · ${count} cells`;
}

const MOVES: Record<string, Cell> = {
  ArrowUp: { col: 0, row: -1 },
  ArrowDown: { col: 0, row: 1 },
  ArrowLeft: { col: -1, row: 0 },
  ArrowRight: { col: 1, row: 0 },
};

export default function App() {
  const [selection, setSelection] = useState<Selection | null>(null);
  const [active, setActive] = useState<Cell>({ col: 0, row: 0 });
  const dragging = useRef(false);
  const cells = useRef(new Map<string, HTMLDivElement>());

  // A drag ends wherever the button comes up, inside the sheet or not.
  useEffect(() => {
    const stop = () => {
      dragging.current = false;
    };
    window.addEventListener('mouseup', stop);
    return () => window.removeEventListener('mouseup', stop);
  }, []);

  const select = (anchor: Cell, focus: Cell) => {
    setSelection({ anchor, focus });
    setActive(focus);
  };

  const onMouseDown = (cell: Cell, event: React.MouseEvent) => {
    event.preventDefault();
    // Shift keeps where the selection started; a plain press starts a new one there.
    if (event.shiftKey && selection) select(selection.anchor, cell);
    else select(cell, cell);
    dragging.current = true;
  };

  const onMouseEnter = (cell: Cell) => {
    if (!dragging.current) return;
    setSelection((current) => (current ? { anchor: current.anchor, focus: cell } : current));
    setActive(cell);
  };

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Escape') {
      setSelection(null);
      return;
    }
    const move = MOVES[event.key];
    if (!move) return;
    event.preventDefault();
    const next = { col: clamp(active.col + move.col, COLUMNS.length - 1), row: clamp(active.row + move.row, ROW_COUNT - 1) };
    if (event.shiftKey) select(selection?.anchor ?? active, next);
    else select(next, next);
    cells.current.get(cellName(next))?.focus();
  };

  const box = selection ? bounds(selection) : null;
  const isSelected = (cell: Cell) =>
    !!box && cell.row >= box.top && cell.row <= box.bottom && cell.col >= box.left && cell.col <= box.right;

  return (
    <main className="sheet-page">
      <p className="selection-summary" role="status">{summary(selection)}</p>
      <div className="sheet" role="grid" aria-label="Seats" aria-multiselectable="true" onKeyDown={onKeyDown}>
        {Array.from({ length: ROW_COUNT }, (_, row) => (
          <div className="sheet-row" role="row" key={row}>
            {COLUMNS.map((_, col) => {
              const cell = { col, row };
              const name = cellName(cell);
              return (
                <div
                  key={name}
                  ref={(node) => {
                    if (node) cells.current.set(name, node);
                    else cells.current.delete(name);
                  }}
                  className="cell"
                  role="gridcell"
                  data-cell={name}
                  aria-selected={isSelected(cell)}
                  tabIndex={col === active.col && row === active.row ? 0 : -1}
                  onMouseDown={(event) => onMouseDown(cell, event)}
                  onMouseEnter={() => onMouseEnter(cell)}
                >
                  {name}
                </div>
              );
            })}
          </div>
        ))}
      </div>
    </main>
  );
}

import React, { useState } from 'react';
import './App.css';

export type Json = string | number | boolean | null | Json[] | { [key: string]: Json };

/** Three samples to load into the input: an object of primitives, a nested playlist and a deep library. */
export const SAMPLES: Record<string, string> = {
  track: JSON.stringify({ title: 'Night Drive', seconds: 214, explicit: false, album: null }, null, 2),
  playlist: JSON.stringify({
    name: 'Focus',
    owner: { id: 7, name: 'Ada' },
    tracks: [
      { title: 'Night Drive', seconds: 214 },
      { title: 'Low Tide', seconds: 187 },
      { title: 'Signal', seconds: 241 },
    ],
    tags: [],
    meta: {},
  }, null, 2),
  library: JSON.stringify({
    shelves: [{ label: 'Jazz', albums: [{ title: 'Blue', tracks: [{ n: 1, title: 'So What', credits: { bass: 'Paul' } }] }] }],
    count: 1,
  }, null, 2),
};

type Parsed = { ok: true; value: Json } | { ok: false; message: string };

function parse(text: string): Parsed {
  try {
    return { ok: true, value: JSON.parse(text) as Json };
  } catch (error) {
    return { ok: false, message: error instanceof Error ? error.message : String(error) };
  }
}

type Container = Json[] | { [key: string]: Json };

function isContainer(value: Json): value is Container {
  return typeof value === 'object' && value !== null;
}

/** How a primitive reads: strings in quotes, the rest as JSON writes them. */
function show(value: string | number | boolean | null): string {
  return JSON.stringify(value);
}

function summary(value: Container): string {
  if (Array.isArray(value)) return `[…] ${value.length} ${value.length === 1 ? 'item' : 'items'}`;
  const keys = Object.keys(value).length;
  return `{…} ${keys} ${keys === 1 ? 'key' : 'keys'}`;
}

interface NodeProps {
  name?: string;
  value: Json;
  path: string;
  collapsed: ReadonlySet<string>;
  onToggle: (path: string) => void;
}

/** One key or index with its value; a container renders its entries by calling itself. */
function JsonNode({ name, value, path, collapsed, onToggle }: NodeProps) {
  const key = name === undefined ? null : <span className="json-key">{name}</span>;
  if (!isContainer(value)) {
    return (
      <li className="json-entry" data-path={path}>
        {key}
        <span className="json-value">{show(value)}</span>
      </li>
    );
  }
  const entries: [string, Json, string][] = Array.isArray(value)
    ? value.map((item, index) => [String(index), item, `${path}[${index}]`])
    : Object.entries(value).map(([child, item]) => [child, item, `${path}.${child}`]);
  if (entries.length === 0) {
    return (
      <li className="json-entry" data-path={path}>
        {key}
        <span className="json-value">{Array.isArray(value) ? '[]' : '{}'}</span>
      </li>
    );
  }
  const open = !collapsed.has(path);
  return (
    <li className="json-entry" data-path={path}>
      <button type="button" className="json-toggle" aria-expanded={open} aria-label={name ?? 'root'} onClick={() => onToggle(path)}>
        {open ? '▾' : '▸'}
      </button>
      {key}
      {open ? (
        <ul className="json-children">
          {entries.map(([child, item, childPath]) => (
            <JsonNode key={child} name={child} value={item} path={childPath} collapsed={collapsed} onToggle={onToggle} />
          ))}
        </ul>
      ) : (
        <span className="json-summary">{summary(value)}</span>
      )}
    </li>
  );
}

export default function App() {
  const [text, setText] = useState(SAMPLES.track);
  // Collapsed nodes by path, so a node keeps its state while the JSON around it changes.
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(new Set());

  const toggle = (path: string) => {
    setCollapsed((current) => {
      const next = new Set(current);
      if (next.has(path)) next.delete(path);
      else next.add(path);
      return next;
    });
  };

  const parsed = parse(text);

  return (
    <main className="json-page">
      <label className="field">
        Sample
        <select className="sample" defaultValue="track" onChange={(event) => setText(SAMPLES[event.target.value])}>
          <option value="track">Track</option>
          <option value="playlist">Playlist</option>
          <option value="library">Library</option>
        </select>
      </label>
      <label className="field">
        JSON
        <textarea className="json-input" rows={10} value={text} onChange={(event) => setText(event.target.value)} />
      </label>
      {'message' in parsed ? (
        <p className="json-error" role="alert">Invalid JSON: {parsed.message}</p>
      ) : (
        <ul className="json-viewer" aria-label="JSON tree">
          <JsonNode value={parsed.value} path="$" collapsed={collapsed} onToggle={toggle} />
        </ul>
      )}
    </main>
  );
}

import React, { useEffect, useRef, useState } from 'react';
import './App.css';

export interface Item {
  id: string;
  text: string;
  done: boolean;
  children: Item[];
}

/** The outline the page opens with. */
export const INITIAL: Item[] = [
  {
    id: 'plan',
    text: 'Plan the launch',
    done: false,
    children: [
      { id: 'draft', text: 'Draft the post', done: false, children: [] },
      { id: 'date', text: 'Pick a date', done: false, children: [] },
    ],
  },
  { id: 'venue', text: 'Book the venue', done: false, children: [] },
  { id: 'invites', text: 'Send invites', done: false, children: [] },
];

let created = 0;
/** A fresh id for a new item. */
export function newId(): string {
  created += 1;
  return `item-${created}`;
}

// The tree operations are pure: each returns a new tree and leaves its input as it was.

/** Where an item sits: the indices of its parents from the top, and its own index among its siblings. */
function locate(items: Item[], id: string, parents: number[] = []): { parents: number[]; index: number } | null {
  for (let index = 0; index < items.length; index += 1) {
    if (items[index].id === id) return { parents, index };
    const inside = locate(items[index].children, id, [...parents, index]);
    if (inside) return inside;
  }
  return null;
}

/** Replaces the sibling list that `parents` leads to. */
function withSiblings(items: Item[], parents: number[], change: (siblings: Item[]) => Item[]): Item[] {
  if (parents.length === 0) return change(items);
  const [first, ...rest] = parents;
  return items.map((item, index) => (index === first ? { ...item, children: withSiblings(item.children, rest, change) } : item));
}

function insertAfter(items: Item[], id: string, fresh: Item): Item[] {
  const at = locate(items, id);
  if (!at) return items;
  return withSiblings(items, at.parents, (siblings) => [...siblings.slice(0, at.index + 1), fresh, ...siblings.slice(at.index + 1)]);
}

/** The item becomes the last child of its previous sibling; a first child stays where it is. */
function indent(items: Item[], id: string): Item[] {
  const at = locate(items, id);
  if (!at || at.index === 0) return items;
  return withSiblings(items, at.parents, (siblings) => {
    const item = siblings[at.index];
    const previous = siblings[at.index - 1];
    return siblings
      .filter((sibling) => sibling.id !== id)
      .map((sibling) => (sibling.id === previous.id ? { ...previous, children: [...previous.children, item] } : sibling));
  });
}

/** The item becomes the next sibling of its parent; its later siblings stay with the parent. A top-level item stays. */
function outdent(items: Item[], id: string): Item[] {
  const at = locate(items, id);
  if (!at || at.parents.length === 0) return items;
  const parentIndex = at.parents[at.parents.length - 1];
  return withSiblings(items, at.parents.slice(0, -1), (siblings) => {
    const parent = siblings[parentIndex];
    const item = parent.children[at.index];
    const rest = { ...parent, children: parent.children.filter((child) => child.id !== id) };
    return [...siblings.slice(0, parentIndex), rest, item, ...siblings.slice(parentIndex + 1)];
  });
}

function remove(items: Item[], id: string): Item[] {
  const at = locate(items, id);
  if (!at) return items;
  return withSiblings(items, at.parents, (siblings) => siblings.filter((sibling) => sibling.id !== id));
}

function update(items: Item[], id: string, change: Partial<Item>): Item[] {
  const at = locate(items, id);
  if (!at) return items;
  return withSiblings(items, at.parents, (siblings) => siblings.map((sibling) => (sibling.id === id ? { ...sibling, ...change } : sibling)));
}

/** Every item in reading order. */
function flatten(items: Item[]): Item[] {
  return items.flatMap((item) => [item, ...flatten(item.children)]);
}

export default function App() {
  const [items, setItems] = useState<Item[]>(INITIAL);
  const [focusId, setFocusId] = useState<string | null>(null);
  const inputs = useRef(new Map<string, HTMLInputElement>());
  const addButton = useRef<HTMLButtonElement | null>(null);

  // An item that moves is a new element: focus follows its id once, after the change that asked for it.
  useEffect(() => {
    if (!focusId) return;
    inputs.current.get(focusId)?.focus();
    setFocusId(null);
  }, [focusId]);

  const all = flatten(items);
  const done = all.filter((item) => item.done).length;

  const onKeyDown = (item: Item, event: React.KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const fresh: Item = { id: newId(), text: '', done: false, children: [] };
      setItems((current) => insertAfter(current, item.id, fresh));
      setFocusId(fresh.id);
    } else if (event.key === 'Tab') {
      event.preventDefault();
      const out = event.shiftKey;
      setItems((current) => (out ? outdent(current, item.id) : indent(current, item.id)));
      setFocusId(item.id);
    } else if (event.key === 'Backspace' && item.text === '' && item.children.length === 0) {
      event.preventDefault();
      const previous = all[all.findIndex((entry) => entry.id === item.id) - 1];
      setItems((current) => remove(current, item.id));
      setFocusId(previous ? previous.id : null);
    } else if (event.key === 'Escape') {
      // The way out of the outline for a keyboard: Tab indents inside it.
      event.preventDefault();
      setFocusId(null);
      addButton.current?.focus();
    }
  };

  const addItem = () => {
    const fresh: Item = { id: newId(), text: '', done: false, children: [] };
    setItems((current) => [...current, fresh]);
    setFocusId(fresh.id);
  };

  const renderList = (list: Item[], className: string) => (
    <ul className={className}>
      {list.map((item) => (
        <li key={item.id} className={item.done ? 'outline-item is-done' : 'outline-item'} data-id={item.id}>
          <input
            type="checkbox"
            className="item-done"
            checked={item.done}
            aria-label={`Done: ${item.text || 'empty item'}`}
            onChange={() => setItems((current) => update(current, item.id, { done: !item.done }))}
          />
          <input
            className="item-text"
            value={item.text}
            aria-label="Item"
            ref={(node) => {
              if (node) inputs.current.set(item.id, node);
              else inputs.current.delete(item.id);
            }}
            onChange={(event) => setItems((current) => update(current, item.id, { text: event.target.value }))}
            onKeyDown={(event) => onKeyDown(item, event)}
          />
          {item.children.length > 0 && renderList(item.children, 'outline-children')}
        </li>
      ))}
    </ul>
  );

  return (
    <main className="outline-page">
      <p className="outline-count" role="status">{done} of {all.length} done</p>
      {renderList(items, 'outline')}
      <button type="button" className="add-item" ref={addButton} onClick={addItem}>New item</button>
    </main>
  );
}

import React, { useEffect, useState } from 'react';
import './App.css';

export interface Command {
  id: string;
  title: string;
}

export interface DocumentHit {
  id: string;
  title: string;
}

/** The app's commands, in the order the palette lists equal matches. */
export const COMMANDS: Command[] = [
  { id: 'new-page', title: 'New page' },
  { id: 'rename-page', title: 'Rename page' },
  { id: 'duplicate-page', title: 'Duplicate page' },
  { id: 'add-tag', title: 'Add new tag' },
  { id: 'new-database', title: 'New database' },
  { id: 'dark-mode', title: 'Toggle dark mode' },
  { id: 'settings', title: 'Settings' },
  { id: 'export-pdf', title: 'Export as PDF' },
  { id: 'renew', title: 'Renew subscription' },
];

/** How long typing must pause before the palette searches documents, in milliseconds. */
export const DEBOUNCE_MS = 150;

/** "Today" for the date phrases: Thursday, 12 March 2026, in local time. */
export const TODAY = new Date(2026, 2, 12);

const DOCUMENTS: DocumentHit[] = [
  { id: 'doc-planning', title: 'Planning notes' },
  { id: 'doc-plugins', title: 'Plugin list' },
  { id: 'doc-launch-plan', title: 'Launch plan' },
  { id: 'doc-launch-retro', title: 'Launch retro' },
  { id: 'doc-pricing', title: 'Pricing page draft' },
  { id: 'doc-playbook', title: 'Team playbook' },
  { id: 'doc-today', title: 'Notes for today' },
];

/**
 * The document search API. A query of one or two characters takes 500 ms and a longer one 120 ms, so answers can
 * arrive in a different order from the requests. A query containing `pdf` fails. An aborted request rejects with an
 * `AbortError`.
 */
export function searchDocuments(query: string, signal?: AbortSignal): Promise<DocumentHit[]> {
  return new Promise((resolve, reject) => {
    const aborted = () => reject(new DOMException('The search was aborted', 'AbortError'));
    if (signal?.aborted) {
      aborted();
      return;
    }
    const timer = window.setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      const needle = query.trim().toLowerCase();
      if (needle.includes('pdf')) reject(new Error('Search is unavailable'));
      else resolve(DOCUMENTS.filter((hit) => hit.title.toLowerCase().includes(needle)));
    }, query.trim().length <= 2 ? 500 : 120);
    const onAbort = () => {
      window.clearTimeout(timer);
      aborted();
    };
    signal?.addEventListener('abort', onAbort);
  });
}

const WEEKDAYS = ['sunday', 'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday'];

function addDays(date: Date, days: number): Date {
  const next = new Date(date);
  next.setDate(next.getDate() + days);
  return next;
}

/** The date a phrase names, counted from `today`: `today`, `tomorrow`, `in N days` or `next <weekday>`. */
export function parseDate(phrase: string, today: Date): Date | null {
  const text = phrase.trim().toLowerCase();
  if (text === 'today') return today;
  if (text === 'tomorrow') return addDays(today, 1);
  const inDays = /^in (\d{1,3}) days?$/.exec(text);
  if (inDays) return addDays(today, Number(inDays[1]));
  const next = /^next ([a-z]+)$/.exec(text);
  if (next) {
    const day = WEEKDAYS.indexOf(next[1]);
    // The first such weekday after today: on a Thursday, `next thursday` is a week away.
    if (day >= 0) return addDays(today, (day - today.getDay() + 7) % 7 || 7);
  }
  return null;
}

/** 0 for a prefix match, 1 for a word that starts with the query, 2 for a match anywhere else, -1 for none. */
function rank(title: string, query: string): number {
  const text = title.toLowerCase();
  if (text.startsWith(query)) return 0;
  if (text.split(' ').some((word) => word.startsWith(query))) return 1;
  return text.includes(query) ? 2 : -1;
}

type Option = { id: string; source: 'command' | 'date' | 'document'; label: string; action: string };
type Documents = { status: 'idle' | 'loading' | 'done' | 'error'; hits: DocumentHit[] };

const pad = (value: number) => String(value).padStart(2, '0');

export default function App() {
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(0);
  const [documents, setDocuments] = useState<Documents>({ status: 'idle', hits: [] });
  const [lastAction, setLastAction] = useState('');

  const needle = query.trim().toLowerCase();

  // One document search per pause in typing. The cleanup cancels the timer and the request, so only the
  // latest query can set the results.
  useEffect(() => {
    if (!needle) {
      setDocuments({ status: 'idle', hits: [] });
      return undefined;
    }
    setDocuments({ status: 'loading', hits: [] });
    const controller = new AbortController();
    const timer = window.setTimeout(() => {
      searchDocuments(needle, controller.signal).then(
        (hits) => setDocuments({ status: 'done', hits }),
        (error: unknown) => {
          if (error instanceof DOMException && error.name === 'AbortError') return;
          setDocuments({ status: 'error', hits: [] });
        },
      );
    }, DEBOUNCE_MS);
    return () => {
      window.clearTimeout(timer);
      controller.abort();
    };
  }, [needle]);

  const commands: Option[] = needle
    ? COMMANDS.map((command, order) => ({ command, order, score: rank(command.title, needle) }))
      .filter((entry) => entry.score >= 0)
      .sort((a, b) => a.score - b.score || a.order - b.order)
      .map(({ command }) => ({ id: `option-command-${command.id}`, source: 'command', label: command.title, action: `Ran: ${command.title}` }))
    : [];
  const date = needle ? parseDate(needle, TODAY) : null;
  const dates: Option[] = date
    ? [{
      id: 'option-date',
      source: 'date',
      label: `Jump to ${date.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}`,
      action: `Jumped to ${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`,
    }]
    : [];
  const hits: Option[] = documents.hits.map((hit) => ({ id: `option-document-${hit.id}`, source: 'document', label: hit.title, action: `Opened: ${hit.title}` }));
  const options = [...commands, ...dates, ...hits];
  const current = options.length ? options[Math.min(active, options.length - 1)] : null;

  const choose = (option: Option) => setLastAction(option.action);

  const onKeyDown = (event: React.KeyboardEvent<HTMLInputElement>) => {
    const count = options.length;
    if (event.key === 'Escape') {
      setQuery('');
      setActive(0);
    } else if (!count) {
      return;
    } else if (event.key === 'ArrowDown') {
      setActive((index) => (Math.min(index, count - 1) + 1) % count);
    } else if (event.key === 'ArrowUp') {
      setActive((index) => (Math.min(index, count - 1) - 1 + count) % count);
    } else if (event.key === 'Home') {
      setActive(0);
    } else if (event.key === 'End') {
      setActive(count - 1);
    } else if (event.key === 'Enter' && current) {
      choose(current);
    } else {
      return;
    }
    event.preventDefault();
  };

  const section = (source: Option['source'], heading: string, list: Option[]) => (list.length > 0 && (
    <div className="palette-section" data-source={source} role="group" aria-label={heading}>
      <p className="palette-heading" aria-hidden="true">{heading}</p>
      {list.map((option) => (
        <div
          key={option.id}
          id={option.id}
          className="palette-option"
          role="option"
          data-source={option.source}
          aria-selected={option.id === current?.id}
          onMouseDown={(event) => event.preventDefault()}
          onClick={() => choose(option)}
        >
          {option.label}
        </div>
      ))}
    </div>
  ));

  return (
    <main className="palette">
      <label className="palette-label" htmlFor="palette-input">Search commands, dates and documents</label>
      <input
        id="palette-input"
        className="palette-input"
        role="combobox"
        aria-expanded={options.length > 0}
        aria-controls="palette-list"
        aria-autocomplete="list"
        aria-activedescendant={current?.id}
        autoComplete="off"
        value={query}
        onChange={(event) => {
          setQuery(event.target.value);
          setActive(0);
        }}
        onKeyDown={onKeyDown}
      />
      {options.length > 0 && (
        <div id="palette-list" className="palette-list" role="listbox" aria-label="Results">
          {section('command', 'Commands', commands)}
          {section('date', 'Dates', dates)}
          {section('document', 'Documents', hits)}
        </div>
      )}
      {documents.status === 'loading' && <p className="palette-loading" role="status">Searching documents…</p>}
      {documents.status === 'error' && <p className="palette-error" role="alert">Could not search documents</p>}
      {documents.status === 'done' && options.length === 0 && <p className="palette-empty">No results</p>}
      <p className="last-action" role="status">{lastAction}</p>
    </main>
  );
}
